-- ===================================================================
-- Japan's Century-Old Shops (334 Heritage Shops) - Supabase Import
-- Source: Google Sheets (Japan's Century-Old Shops with Regions)
-- Run this script in your Supabase SQL Editor.
-- ===================================================================

-- 1. Ensure required columns and safe defaults exist on century_shops
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS rating DECIMAL(3, 2) DEFAULT 0;
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS reviews_count INTEGER DEFAULT 0;
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS subcategory TEXT;
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS address TEXT;
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS website TEXT;
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS flavor_type TEXT;
ALTER TABLE public.century_shops ADD COLUMN IF NOT EXISTS seasonal_tag TEXT;

-- 2. Ensure auto-incrementing ID sequence if not already an identity column
DO $$ 
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'century_shops' 
        AND column_name = 'id' 
        AND (column_default IS NOT NULL OR is_identity = 'YES')
    ) THEN
        CREATE SEQUENCE IF NOT EXISTS public.century_shops_id_seq;
        ALTER TABLE public.century_shops ALTER COLUMN id SET DEFAULT nextval('public.century_shops_id_seq');
        PERFORM setval('public.century_shops_id_seq', COALESCE((SELECT MAX(id) FROM public.century_shops), 0) + 1);
    END IF;
END $$;

-- 3. Ensure Row Level Security allows public read
ALTER TABLE public.century_shops ENABLE ROW LEVEL SECURITY;
DO $$ 
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'century_shops' AND policyname = 'Anyone can view shops'
    ) THEN
        CREATE POLICY "Anyone can view shops" ON public.century_shops FOR SELECT USING (true);
    END IF;
END $$;

-- 4. Insert all 334 Century-Old Shops (skips if already exists by shop_name + prefecture)
INSERT INTO public.century_shops (
    shop_name, prefecture, region, founded, category, pin_type,
    flavor_type, subcategory, description, website, address,
    lat, lng, image_url, rating, reviews_count
)
SELECT 
    v.shop_name, v.prefecture, v.region, v.founded, v.category, v.pin_type,
    v.flavor_type, v.subcategory, v.description, v.website, v.address,
    v.lat, v.lng, v.image_url, v.rating, v.reviews_count
FROM (
    VALUES
    ('Toshimaya', 'Kanagawa', 'Kanto', '1894', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A leading long-established Japanese sweets shop in Kamakura, nationally known for signature confections including the Hato Sablé (dove-shaped butter cookie). Since its founding it has stayed true to careful ingredient selection and handmade tradition, growing alongside Kamakura''s culture. Beloved by locals and visitors alike as one of Kanagawa''s premier shops.', 'https://www.hato.co.jp', 'Kanagawa, Japan', 35.32035423994246, 139.55263380458294, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 105),
    ('Uirou', 'Kanagawa', 'Kanto', 'c. 1368', 'food', 'food', 'sweet', 'Japanese sweets / traditional medicine', 'One of Japan''s foremost long-established shops, dating back to the Muromachi period, producing and selling Odawara''s famous "uirou" confection and traditional medicine. Its historic storefront is a well-known landmark of the old Odawara castle town, still preserving the recipes and hospitality passed down through its long history.', 'https://www.uirou.co.jp', 'Kanagawa, Japan', 35.247455205015335, 139.15601344273594, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 151),
    ('Suzuhiro Kamaboko', 'Kanagawa', 'Kanto', '1865', 'food', 'food', 'savory', 'Kamaboko (fish cake)', 'A leading kamaboko maker in Odawara with over 150 years of history. It continues to craft products from carefully selected fish using traditional techniques, while its "Kamaboko no Sato" complex offers factory tours and hands-on workshops that spread Japanese food culture widely.', 'https://www.kamaboko.com', 'Kanagawa, Japan', 35.24608217135508, 139.12995562299696, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 178),
    ('Yamajo Kamaboko-ten', 'Kanagawa', 'Kanto', '1878', 'food', 'food', 'savory', 'Kamaboko (fish cake)', 'A long-established kamaboko shop in Odawara founded in the Meiji era. It insists on the traditional stone-mill method to bring out the natural flavor of the fish, earning the trust of many customers through its long-inherited techniques and commitment to quality.', 'https://yamajoukamaboko.co.jp', 'Kanagawa, Japan', 35.25139382877999, 139.16607256441793, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 142),
    ('Nakazawa Shuzo', 'Kanagawa', 'Kanto', '1825', 'food', 'food', NULL, 'Sake brewing', 'A long-established sake brewery in Matsuda with roughly 200 years of history. Its flagship brand "Matsu Midori" is known as a representative sake of Kanagawa Prefecture, made by blending traditional technique with modern quality control.', 'https://www.matsumidori.jp', 'Kanagawa, Japan', 35.34638502767067, 139.1370816220897, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 157),
    ('Izumibashi Shuzo', 'Kanagawa', 'Kanto', '1857', 'food', 'food', NULL, 'Sake brewing', 'A long-established sake brewery in Ebina City with over 160 years of history. Guided by the philosophy that "sake brewing starts with rice growing," it brews sake using rice grown on its own fields and by contracted farmers, and is highly regarded at home and abroad for its environmentally conscious brewing.', 'https://izumibashi.com', 'Kanagawa, Japan', 35.46569089458483, 139.3905745220897, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 47),
    ('Kumazawa Shuzo', 'Kanagawa', 'Kanto', '1872', 'food', 'food', NULL, 'Sake brewing', 'A long-established sake brewery in Chigasaki, Shonan, that has continued brewing for over 150 years. Its flagship brand "Tensei" is known as a sake that reflects the local terroir. The premises also house a restaurant, bakery, and gallery, making it a popular spot where food and culture come together.', 'https://www.kumazawa.jp', 'Kanagawa, Japan', 35.36067869221126, 139.40184012208974, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 35),
    ('Nozawa Sakuzo Shoten', 'Kanagawa', 'Kanto', '1875', 'food', 'food', NULL, 'Food / local specialty goods', 'Founded in Odawara, this long-established shop is now beloved for handling regional specialty products and traditional crafts. Drawing on its long-honed eye for quality, it sells carefully selected goods and shares the appeal of Odawara and Hakone nationwide, both in its physical store and online shop.', 'https://nozawasakuzo.com', 'Kanagawa, Japan', 35.25070931559079, 139.16179179140258, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 52),
    ('Ebisuya Honten', 'Kanagawa', 'Kanto', 'Meiji era', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has been operating in Fujisawa for many years. It produces and sells seasonal Japanese sweets and locally rooted confections beloved by local residents, offering a rich lineup of gifts and seasonal items while preserving traditional techniques.', 'https://ebisuyahonten.jp', 'Kanagawa, Japan', 35.39345563678103, 139.40558982208972, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 144),
    ('Kamakura Ham Tomioka Shokai', 'Kanagawa', 'Kanto', '1900', 'food', 'food', 'savory', 'Food manufacturing (ham & sausage)', 'A long-established food maker founded in Meiji 33 (1900). It carries on ham- and sausage-making techniques handed down from Germany, producing authentic products that are also popular as gifts. It has supported the Japanese dining table for many years as a leading Kanagawa Prefecture brand.', 'https://www.kamakuraham-tomioka.co.jp', 'Kanagawa, Japan', 35.322681835313304, 139.55174650244138, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 100),
    ('Sumiyoshi (Kuzumochi)', 'Kanagawa', 'Kanto', '1907', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has operated for over 100 years in the temple town in front of Kawasaki Daishi. Its signature kuzumochi is made using an old-fashioned method, known for its simple yet refined flavor. Long loved by worshippers and locals alike, it is known as a representative confection of Kawasaki.', 'https://www.kuzumochi.com', 'Kanagawa, Japan', 35.53479664546409, 139.7306260932538, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 36),
    ('Ninben', 'Tokyo', 'Kanto', '1699', 'food', 'food', 'savory', 'Bonito flakes / food', 'Founded in Genroku 12, a leading long-established food shop in Nihonbashi. It has long supported bonito-flake and dashi (broth) culture, delivering authentic dashi essential to Japanese cuisine nationwide. Its Nihonbashi flagship store sells freshly shaved bonito flakes and various dashi products, keeping Japanese food culture alive today.', 'https://www.ninben.co.jp', 'Tokyo, Japan', 35.686772783309685, 139.77404150674622, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 142),
    ('Eitaro Sohonpo', 'Tokyo', 'Kanto', '1857', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A leading long-established Japanese sweets shop in Nihonbashi. Alongside signature products such as "Eitaro Ame" candy and kintsuba, it preserves traditional flavors while also pursuing new confectionery. A celebrated shop that carries Edo-era confectionery culture into the present, beloved by many.', 'https://www.eitaro.com', 'Tokyo, Japan', 35.68767647366626, 139.7720545143473, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 145),
    ('Bunmeido Tokyo', 'Tokyo', 'Kanto', '1900', 'food', 'food', 'sweet', 'Japanese & Western confectionery', 'A long-established confectioner known for castella sponge cake. Using carefully selected ingredients and a recipe passed down since founding, its castella is loved across generations. Its Nihonbashi flagship store also offers limited-edition items and a café.', 'https://www.bunmeido.co.jp', 'Tokyo, Japan', 35.68650645674785, 139.7752825064627, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 73),
    ('Miharado Honten', 'Tokyo', 'Kanto', '1877', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has operated in Ningyocho for over 140 years. It offers a rich lineup including salted rice crackers, monaka wafers, and seasonal fresh sweets, and is also known for confections associated with Suitengu Shrine. Highly popular as gifts.', 'https://www.miharado-honten.co.jp', 'Tokyo, Japan', 35.68401652022966, 139.7842026200173, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 86),
    ('Kamezawado', 'Tokyo', 'Kanto', '1905', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop in Kanda-Jimbocho that has continued for over 120 years. Craftsmen hand-make dorayaki, mame-daifuku, and fresh sweets daily. Known for its dedication to ingredient selection and technique, it remains beloved by the local community.', 'https://kamezawado.co.jp', 'Tokyo, Japan', 35.69684597109844, 139.75814594927218, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 76),
    ('Funawa', 'Tokyo', 'Kanto', '1902', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 35, a long-established Japanese sweets shop nationally known for Asakusa''s famous "imo yokan" sweet-potato confection. Its simple flavor, drawing out the natural sweetness of sweet potato, has been loved for many years. Anko-dama and seasonal sweets are also popular items.', 'https://www.funawa.jp', 'Tokyo, Japan', 35.71215092784899, 139.79467716441792, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 154),
    ('Kibundo Sohonten', 'Tokyo', 'Kanto', '1900', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop in Shimbashi that has continued for over 100 years. It keeps producing sweets that highlight the character of its ingredients, including its signature "Aioi Monaka" and dorayaki. A Tokyo shop popular with local companies and businesspeople alike.', 'https://www.kibundou.com', 'Tokyo, Japan', 35.568142723455644, 139.55862326256673, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 110),
    ('Ginza Kikunoya', 'Tokyo', 'Kanto', '1890', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established confectioner founded in Meiji 23. Its colorful Edo-style confection "Fukiyose" is highly popular as a gift. It offers beautiful sweets that blend modern sensibility while preserving traditional techniques.', 'https://www.ginza-kikunoya.co.jp', 'Tokyo, Japan', 35.6704911912781, 139.76271689325384, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 132),
    ('Aono Sohonpo', 'Tokyo', 'Kanto', '1856', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Ansei 3, a long-established Japanese sweets shop with nearly 170 years of history in Roppongi. Craftsmen carefully finish seasonal sweets including its signature "Uguisu Mochi" and dorayaki. A shop deeply rooted in and loved by the local community.', 'https://www.azabu-aono.com', 'Tokyo, Japan', 35.662334053529335, 139.73526736441795, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 94),
    ('Yamamoto Noriten', 'Tokyo', 'Kanto', '1849', 'food', 'food', 'savory', 'Nori seaweed / food', 'Founded in Kaei 2, a leading long-established nori specialty shop in Nihonbashi. It handles high-quality roasted and seasoned nori as well as many gift items. For over 170 years it has put quality first in nori-making, beloved at home and abroad as a shop that supports Japanese food culture.', 'https://www.yamamoto-noriten.co.jp', 'Tokyo, Japan', 35.684623316826986, 139.77514220674615, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.6, 123),
    ('Nihonbashi Benmatsu Sohonten', 'Tokyo', 'Kanto', '1850', 'food', 'food', 'savory', 'Bento (boxed meals)', 'Founded in Kaei 3, known as one of Japan''s oldest catering bento shops. Characterized by the bold seasoning handed down since its founding, it continues to preserve Edo-style flavors centered on simmered dishes. A long-established bento shop popular at Tokyo Station and department stores.', 'https://www.benmatsu.com', 'Tokyo, Japan', 35.6855999287856, 139.77582833558205, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 90),
    ('Kokubu Group Honsha', 'Tokyo', 'Kanto', '1712', 'shop', 'shop', NULL, 'Food wholesale', 'A leading Japanese food-wholesale company founded in the Edo period. Starting from alcohol sales, it has grown into a comprehensive food company supporting food distribution. With over 300 years of inherited trust and track record, it continues to support Japan''s food culture.', 'https://www.kokubu.co.jp', 'Tokyo, Japan', 35.683872604628064, 139.7736127871505, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 104),
    ('Nihonbashi Kiya', 'Tokyo', 'Kanto', '1792', 'shop', 'shop', NULL, 'Cutlery / cookware', 'Founded in Kansei 4, a long-established cutlery specialty shop in Nihonbashi. Centered on kitchen knives and cooking tools, it is widely supported by professional chefs and households alike. It handles high-quality products from skilled craftsmen, carrying Japan''s manufacturing culture into the present.', 'https://www.kiya-hamono.co.jp', 'Tokyo, Japan', 35.686790887186795, 139.7740106247227, 'https://images.unsplash.com/photo-1584992236310-6edddc08acff?w=800&auto=format&fit=crop&q=80', 4.7, 112),
    ('Sohonke Sarashina Horii', 'Tokyo', 'Kanto', '1789', 'food', 'food', 'savory', 'Soba noodles', 'A leading long-established soba shop in Tokyo dating from the Edo period. Its beautiful white "sarashina" soba has long been loved by writers and gourmets. It continues to serve high-quality soba and seasonal dishes while preserving traditional technique.', 'https://www.sarashina-horii.com', 'Tokyo, Japan', 35.657019935418425, 139.73288566441795, 'https://images.unsplash.com/photo-1618841557871-b4664fbf0cb3?w=800&auto=format&fit=crop&q=80', 4.8, 185),
    ('Ningyocho Imahan', 'Tokyo', 'Kanto', '1895', 'food', 'food', NULL, 'Sukiyaki / shabu-shabu', 'Rooted in a long-established gyunabe (beef hot pot) restaurant founded in Meiji 28, nationally known for sukiyaki and shabu-shabu made with high-quality Kuroge Wagyu beef. With years of honed judgment and hospitality, it offers a special dining experience to many.', 'https://www.imahan.co.jp', 'Tokyo, Japan', 35.6858922996233, 139.78363394907436, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop&q=80', 4.7, 168),
    ('Isehan (Beni Museum)', 'Tokyo', 'Kanto', '1825', 'shop', 'shop', NULL, 'Beni (traditional rouge) / cosmetics', 'Founded in Bunsei 8, the only long-established shop in Japan carrying on traditional beni (safflower rouge) making. It continues to preserve natural beni made from safflowers into the present, widely sharing Japan''s cosmetic culture and aesthetics. Its attached Beni Museum lets visitors explore this history.', 'https://www.isehan-beni.co.jp', 'Tokyo, Japan', 35.660050756217046, 139.71794044907435, 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=800&auto=format&fit=crop&q=80', 4.9, 98),
    ('Funabashiya', 'Tokyo', 'Kanto', '1805', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Bunka 2. A long-established Japanese sweets shop born in front of Kameido Tenjin Shrine. Its signature "kuzumochi" is made by a traditional method of long-fermenting wheat starch, preserving a flavor unchanged since the Edo period. Nationally known as a representative confection of Tokyo.', 'https://www.funabashiya.co.jp', 'Tokyo, Japan', 35.70181553790876, 139.81991390489492, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 188),
    ('Komagata Dozeu', 'Tokyo', 'Kanto', '1801', 'food', 'food', 'savory', 'Japanese cuisine (loach dishes)', 'A loach-dish specialty restaurant continuing for over 220 years since the Edo period. Its "dojo-nabe" (loach hot pot), simmered in a secret sauce, is beloved as an Asakusa specialty. The Edo-flavored interior and traditional taste are also popular with visitors from Japan and abroad.', 'https://www.dozeu.com', 'Tokyo, Japan', 35.707637554471354, 139.79501613558205, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 184),
    ('Asakusa Imahan', 'Tokyo', 'Kanto', '1895', 'food', 'food', 'savory', 'Sukiyaki / beef dishes', 'Founded in Meiji 28. A long-established restaurant known for sukiyaki and shabu-shabu made with carefully selected Kuroge Wagyu beef. With traditional hospitality and high-quality cuisine, it has long been loved as a representative shop of Asakusa.', 'https://www.asakusaimahan.co.jp', 'Tokyo, Japan', 35.71391435537289, 139.79222239447333, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop&q=80', 4.7, 76),
    ('Aokiya', 'Tokyo', 'Kanto', '1893', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 26. A long-established confectioner representing the Musashino area with over 100 years of history. It produces Japanese and Western sweets built around its signature "Musashino Nisshi" and homemade red bean paste, widely loved throughout the Tama region.', 'https://aokiya.net', 'Tokyo, Japan', 35.67746041226098, 139.50542647668652, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 87),
    ('Okashitsukasa Kameya (Suginami)', 'Tokyo', 'Kanto', '1917', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 6. It is particular about ingredient selection, carefully hand-making Japanese sweets using Hokkaido-grown azuki beans and wasanbon sugar. A shop rooted in its community that continues to offer sweets for every season.', 'https://www.kameyakasi.co.jp', 'Tokyo, Japan', 35.70709811975126, 139.61635667539213, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 98),
    ('Toraya Akasaka Store', 'Tokyo', 'Kanto', 'Late 16th century (Tokyo store)', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A leading long-established Japanese sweets maker founded in Kyoto in the late Muromachi period. Its present-day Tokyo Akasaka store sells yokan and seasonal fresh sweets carrying traditional prestige. Highly regarded both in Japan and abroad.', 'https://www.toraya-group.co.jp', 'Tokyo, Japan', 35.67541300017923, 139.7325902043825, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 109),
    ('Shiose Sohonke', 'Tokyo', 'Kanto', '1349', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Known as one of Japan''s oldest Japanese sweets shops, carrying on tradition from the Muromachi period. Craftsmen carefully finish signature manju buns as well as seasonal fresh sweets and yokan. Its long-cultivated technique and prestige continue to captivate many people today.', 'https://www.shiose.co.jp', 'Tokyo, Japan', 35.667668073428715, 139.77893456375236, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 172),
    ('Baikatei', 'Tokyo', 'Kanto', '1850', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop founded in the late Edo period. Craftsmen carefully continue to make seasonal fresh sweets, dorayaki, and chestnut steamed yokan. It preserves tradition while also taking on new confectionery, supported by many sweets fans.', 'https://www.baikatei.co.jp', 'Tokyo, Japan', 35.70304971523521, 139.7369683177889, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 135),
    ('Azuma Arare Honpo', 'Tokyo', 'Kanto', '1910', 'food', 'food', 'savory', 'Rice crackers', 'A long-established arare (rice cracker) specialty shop founded in Meiji 43. It produces arare, okaki, and senbei using domestic rice by old-fashioned methods. Products that value the ingredients'' natural flavor are also popular as gifts, loved by many.', 'https://www.azuma-arare.co.jp', 'Tokyo, Japan', 35.6974556640615, 139.80088929325382, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 40),
    ('Seigetsudo Honten', 'Tokyo', 'Kanto', '1907', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 40, a long-established Japanese sweets shop that has continued for over 100 years in Ginza. Craftsmen carefully finish seasonal fresh sweets, yokan, and monaka. A representative Ginza confectioner beloved by many while preserving traditional technique.', 'https://www.seigetsudo-honten.co.jp', 'Tokyo, Japan', 35.666779361552486, 139.76500286441794, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 183),
    ('Kikunoya Honten', 'Tokyo', 'Kanto', '1890', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 23. A long-established confectioner nationally known for its colorful dried sweet "Fukiyose." Its beautiful assortments, made with a craftsman''s delicate skill, are popular as gifts and are one of Tokyo''s representative confections.', 'https://www.ginza-kikunoya.co.jp', 'Tokyo, Japan', 35.67044901655531, 139.76519327254158, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 126),
    ('Shiba Shinmei Eitaro', 'Tokyo', 'Kanto', '1885', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 18 as a noren-wake (branch shop) of Nihonbashi Eitaro Sohonpo. This long-established Japanese sweets shop continues to carefully hand-make sweets that highlight the character of their ingredients, led by its signature "Enoshima Monaka." A shop long loved in Shiba-Daimon, Minato Ward.', 'https://www.shiba-eitaro.com', 'Tokyo, Japan', 35.65808926326031, 139.7543604202385, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 168),
    ('Tsuboya Sohonten (Tokyo Store)', 'Tokyo', 'Kanto', '1806', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop founded in the Edo period. It offers a seasonal lineup of sweets led by its signature "Kihana." It cherishes tradition while also taking on new confectionery, supported by many sweets fans.', 'https://tsuboya.net', 'Tokyo, Japan', 43.75249160438491, 142.37222443770014, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 62),
    ('Sasanoyuki', 'Tokyo', 'Kanto', '1691', 'food', 'food', 'savory', 'Tofu cuisine', 'Founded in Genroku 4, one of Japan''s oldest tofu-cuisine specialty restaurants. Centered on tofu dishes handed down from the Edo period, it offers cuisine that values the natural flavor of its ingredients. A leading Tokyo shop long loved by writers and literati.', 'https://www.sasanoyuki.com', 'Tokyo, Japan', 35.72447003821429, 139.77653268845273, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.8, 45),
    ('Ginza Kimuraya', 'Tokyo', 'Kanto', '1869', 'food', 'food', 'sweet', 'Bakery', 'Founded in Meiji 2, known as the shop that originated Japan''s "anpan" (red-bean-filled bread). Led by its sake-yeast anpan, its bread baked with a traditional recipe is highly popular in Japan and abroad. One of Ginza''s representative shops.', 'https://www.ginzakimuraya.jp', 'Tokyo, Japan', 35.67182472113256, 139.76524482208973, 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', 4.9, 138),
    ('Shiseido Parlour', 'Tokyo', 'Kanto', '1902', 'food', 'food', 'sweet', 'Western cuisine / Western confectionery', 'Founded in Meiji 35, a long-established restaurant and confectioner representing Ginza. Known as the shop that helped spread Western cuisine and sweets in Japan, it continues to offer high-quality hospitality while preserving its traditional recipes.', 'https://parlour.shiseido.co.jp', 'Tokyo, Japan', 35.67074829090218, 139.7032572761627, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 63),
    ('Tokiwado Kaminari-okoshi Honpo', 'Tokyo', 'Kanto', '1877', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 10. A long-established confectioner whose signature product is Asakusa''s famous "Kaminari-okoshi" puffed-rice sweet. Its fragrant rice confection has long been loved as a Tokyo souvenir and is popular with visitors from Japan and abroad as a representative Nakamise-dori flavor.', 'https://tokiwado.tokyo', 'Tokyo, Japan', 35.71123150685584, 139.79614773558205, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 54),
    ('Kameido Masumoto', 'Tokyo', 'Kanto', '1905', 'food', 'food', 'savory', 'Bento / Japanese cuisine', 'Founded in Meiji 38. A long-established shop known for dishes using Kameido daikon radish and its "Sumida River Asari Rice." It continues to offer catering bento and kaiseki cuisine while cherishing Tokyo''s local dishes.', 'https://www.masumoto.co.jp', 'Tokyo, Japan', 35.701700496198434, 139.82584215992853, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.6, 131),
    ('Bairindo (Asakusa Nakamise)', 'Tokyo', 'Kanto', '1854', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established shop that has operated on Asakusa''s Nakamise-dori for over 150 years. It sells classic Asakusa confections such as ningyo-yaki and kawara-senbei. A representative Nakamise shop loved by tourists and local residents alike.', 'https://www.bairindo.co.jp', 'Tokyo, Japan', 36.153949505479176, 139.3848438509256, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 135),
    ('Chikuyotei Honten', 'Tokyo', 'Kanto', '1866', 'food', 'food', 'savory', 'Eel / Japanese cuisine', 'Founded in Keio 2, a leading long-established eel restaurant in Ginza. Using carefully selected domestic eel, its grilled eel prepared with traditional technique is loved by many gourmets. Also known as a prestigious Japanese restaurant.', 'https://www.chikuyotei.com', 'Tokyo, Japan', 34.66394633320395, 135.5023836288359, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 108),
    ('Iseju', 'Tokyo', 'Kanto', '1869', 'food', 'food', 'savory', 'Sukiyaki / beef hot pot', 'Founded in Meiji 2, a long-established gyunabe restaurant that has continued for over 150 years in Kodenmacho, Nihonbashi. Committed to domestic Kuroge Wagyu beef, it serves sukiyaki and gyunabe with a traditional warishita sauce. In its calm space, the craftsman''s technique passed down since founding carries Tokyo''s food culture into the present.', 'https://www.iseju.com', 'Tokyo, Japan', 35.69194795808234, 139.78068745460794, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop&q=80', 4.7, 92),
    ('Muromachi Sunaba', 'Tokyo', 'Kanto', '1872', 'food', 'food', 'savory', 'Soba noodles', 'Founded in Meiji 5, a long-established soba shop in Muromachi, Nihonbashi. It carries on the tradition of Edo-style soba and is known as the shop that originated "tenzaru" (tempura with cold soba). Handmade soba and traditional dipping sauce continue to captivate many people today.', 'https://www.muromachi-sunaba.co.jp', 'Tokyo, Japan', 35.68953609114609, 139.77185226626915, 'https://images.unsplash.com/photo-1618841557871-b4664fbf0cb3?w=800&auto=format&fit=crop&q=80', 4.6, 63),
    ('Matsuzaki Senbei', 'Tokyo', 'Kanto', '1804', 'food', 'food', 'savory', 'Rice crackers', 'Founded in Bunka 1, a long-established rice-cracker shop that has continued for over 200 years in Ginza. Centered on kawara-senbei, it offers products carrying on Edo confectionery culture. Valuing craftsmanship, it continues to blend tradition with modern sensibility.', 'https://matsuzaki-senbei.com', 'Tokyo, Japan', 35.670278339862094, 139.7693422031473, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 86),
    ('Shichiken (Yamanashi Meijo)', 'Yamanashi', 'Chubu', '1750', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kanen 3, a long-established sake brewery in Hakushu, Hokuto City with roughly 270 years of history. It continues to brew sake using groundwater from Mt. Kaikoma in the Southern Alps; its flagship brand "Shichiken" is highly regarded nationwide. Brewery tours and a restaurant are also on site, promoting Yamanashi''s sake culture.', 'https://www.sake-shichiken.co.jp', 'Yamanashi, Japan', 35.80847370932311, 138.3428518048949, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 68),
    ('Kinseiken', 'Yamanashi', 'Chubu', '1903', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop founded in Meiji 36. Known for its "Shingen Mochi" and seasonal fresh sweets made with local rice and natural Southern Alps spring water. It preserves confectionery that values the ingredients'' natural flavor, beloved as a leading Yamanashi sweets shop.', 'https://www.kinseiken.co.jp', 'Yamanashi, Japan', 35.80798161903092, 138.34251073558204, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 165),
    ('Shorinken Toyoshimaya', 'Yamanashi', 'Chubu', '1832', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Tenpo 3, a long-established Japanese sweets shop that has continued for over 190 years in Kofu City. It carefully produces sweets made with local ingredients, led by its signature "Tsuki no Shizuku" and "Kinu-ta Gurumi." It preserves tradition while continuing community-rooted confectionery.', 'https://shourinken.com', 'Yamanashi, Japan', 35.65427758338865, 138.60350413558206, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 93),
    ('Sawadaya', 'Yamanashi', 'Chubu', '1911', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop founded in Meiji 44. Its signature confection "Kurodama" is nationally known as a representative Yamanashi sweet. It preserves traditional methods while taking on new confectionery, loved across generations.', 'https://www.kurodama.co.jp', 'Yamanashi, Japan', 35.66232614013021, 138.57159693902656, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 136),
    ('Okashitsukasa Sugaya', 'Yamanashi', 'Chubu', '1909', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has operated in Tsuru City for over 100 years. Craftsmen carefully hand-make fresh sweets and baked sweets that reflect the local seasons. It preserves the traditional flavor handed down since founding, a shop loved by the community.', 'https://hattan.jp', 'Yamanashi, Japan', 34.81224738367441, 135.3696302037, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 112),
    ('Kashidokoro Matsunoya', 'Yamanashi', 'Chubu', '1907', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established confectioner founded in Meiji 40. Known for "fruit dorayaki" made with Yamanashi-grown fruit and creative Japanese sweets that make use of local specialties. Valuing local production for local consumption, it shares Yamanashi''s appeal through its confections.', 'https://okashi-matsunoya.jp', 'Yamanashi, Japan', 35.66263900326877, 138.4651401085974, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 48),
    ('Ishizakaya', 'Yamanashi', 'Chubu', 'c. 1924', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has continued for over 100 years in Kofu City. It handmakes fresh sweets, sekihan (red rice), and mochi confections that value seasonal character. Loved by many as a sweets shop supporting local celebrations and annual events.', 'https://ishizakaya.com', 'Yamanashi, Japan', 35.672960213480934, 138.56723433558204, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 42),
    ('Yamaki Shuzoten', 'Yamanashi', 'Chubu', '1862', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunkyu 2, a long-established sake brewery that has continued for over 160 years in Takane-cho, Hokuto City. Its flagship brand "Kai Otokoyama" has long been loved locally. The family continues to preserve tradition while brewing sake that reflects the local terroir.', 'https://www.yamanashi-sake.jp/brewery/yamaki-shuzoten/', 'Yamanashi, Japan', 35.803627507176444, 138.409319360825, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 182),
    ('Kikyoya', 'Yamanashi', 'Chubu', '1889', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 22. A leading long-established confectionery maker in Yamanashi, nationally known for its signature "Kikyo Shingen Mochi." Beyond preserving traditional flavor, it widely promotes Yamanashi''s food culture and tourism appeal through factory tours and theme-park operations.', 'https://kikyouya.co.jp', 'Yamanashi, Japan', 36.69204285735723, 137.8611031374333, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 94),
    ('Yorozuya Jozoten', 'Yamanashi', 'Chubu', '1790', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kansei 2, a long-established sake brewery that has continued for over 230 years in Fujikawa Town. Its flagship brand "Shunnoten" uses Southern Alps spring water and carefully selected sake rice, earning high praise for its traditional brewing. It also shares Yamanashi''s sake culture through brewery tours.', 'https://www.shunnoten.co.jp', 'Yamanashi, Japan', 35.56070513038296, 138.46701552208972, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 187),
    ('Sasaichi Shuzo', 'Yamanashi', 'Chubu', '1661', 'food', 'food', NULL, 'Sake brewing', 'A long-established sake brewery founded in the early Edo period. It brews the sake "Sasaichi" in Otsuki City, drawing on a rich natural environment and pure water. Its on-site facilities offer tastings and tours, and it is loved as one of Yamanashi''s leading sake breweries.', 'https://www.sasaichi.co.jp', 'Yamanashi, Japan', 35.60416270201177, 138.83072812532106, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 38),
    ('Tanizakura Shuzo', 'Yamanashi', 'Chubu', '1848', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kaei 1, a long-established sake brewery that has continued for over 170 years in Hokuto City. Using famous water nurtured by the nature of the Yatsugatake mountains and Southern Alps, it continues careful sake brewing. Its flagship brand "Tanizakura" is loved both within and outside the prefecture.', 'https://www.tanizakura.co.jp', 'Yamanashi, Japan', 35.861108747692214, 138.38299023558204, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 76),
    ('Takenoi Shuzo', 'Yamanashi', 'Chubu', '1865', 'food', 'food', NULL, 'Sake brewing', 'Founded in Keio 1, a brewery with 160 years of history in Hokuto City. Drawing on high-quality local water and sake rice, it brews distinctive sake while preserving traditional methods. Loved as a brewery that walks alongside its community.', 'https://www.takenoishuzo.jp', 'Yamanashi, Japan', 35.827295175786766, 138.42676107791027, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 80),
    ('Lumiere', 'Yamanashi', 'Chubu', '1885', 'food', 'food', NULL, 'Winery', 'Founded in Meiji 18. A leading long-established winery in Yamanashi dating from the dawn of Japan''s wine culture. Guided by the philosophy that "real wine comes from real grapes," it handles everything from cultivation on its own farms to production, making a major contribution to improving the quality of Japanese wine.', 'https://www.lumiere.jp', 'Yamanashi, Japan', 35.65453974143493, 138.71131056441794, 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?w=800&auto=format&fit=crop&q=80', 4.8, 37),
    ('Marufuji Winery', 'Yamanashi', 'Chubu', '1890', 'food', 'food', NULL, 'Winery', 'Founded in Meiji 23, a long-established winery that has continued for over 130 years in Katsunuma. Its flagship brand "Rubaiyat" is highly regarded both in Japan and abroad. It values tradition while continuing to make high-quality wine that highlights the character of Yamanashi-grown grapes.', 'https://www.rubaiyat.jp', 'Yamanashi, Japan', 35.6501476632889, 138.71462507791028, 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?w=800&auto=format&fit=crop&q=80', 4.7, 44),
    ('Haramo Wine', 'Yamanashi', 'Chubu', '1924', 'food', 'food', NULL, 'Winery', 'Founded in Taisho 13. Also known for its historic Japanese-style winery building, it brews distinctive wines using Yamanashi-grown grapes. It continues careful winemaking from grape cultivation through production, loved by many wine enthusiasts.', 'https://www.haramo.com', 'Yamanashi, Japan', 35.6650914, 138.731636, 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?w=800&auto=format&fit=crop&q=80', 4.8, 109),
    ('Katsunuma Jozo', 'Yamanashi', 'Chubu', '1937', 'food', 'food', NULL, 'Winery', 'Founded in Showa 12. Committed to Koshu grapes, it continues to make Japan''s leading Koshu wine. (Note: as it has not yet reached 100 years since founding, it is recommended to exclude this entry from any "100+ years" listing.)', 'https://www.katsunuma-winery.com', 'Yamanashi, Japan', 35.6561319, 138.7157307, 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?w=800&auto=format&fit=crop&q=80', 4.9, 142),
    ('Tanizakura Shuzo', 'Yamanashi', 'Chubu', '1848', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kaei 1. A long-established sake brewery brewing the sake "Tanizakura" using famous water nurtured by the nature of the southern foothills of Yatsugatake. It carries on sake brewing that values the local terroir, supported by many sake fans.', 'https://www.tanizakura.co.jp', 'Yamanashi, Japan', 35.8608392, 138.3829956, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 76),
    ('Mataichian', 'Shizuoka', 'Chubu', '1871', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 4, a leading long-established Japanese sweets shop in Iwata City. Led by its signature kintsuba, it continues making Japanese sweets and wa-sweets while preserving traditional methods. Having grown alongside the history of the Mitsuke post town, it is loved by locals and tourists alike.', 'https://www.mataichian.com', 'Shizuoka, Japan', 34.74381, 137.858239, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 86),
    ('Shohakudo Honten', 'Shizuoka', 'Chubu', '1867', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Keio 3, a long-established Japanese sweets shop that has continued for over 150 years in Shizuoka City. Craftsmen carefully produce fresh sweets, monaka, and seasonal confections one by one. Loved by the community for its technique and dedication to ingredients passed down through generations.', 'https://shohakudo.stores.jp', 'Shizuoka, Japan', 34.979506, 138.387806, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 192),
    ('Kenjo Kaho Otakeya', 'Shizuoka', 'Chubu', '1912', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 45, a long-established Japanese sweets shop that has continued for over 100 years in Kikugawa City. It sells signature products such as karinto manju, hyakunen-mochi, and Kikugawa monaka, and is also known for confections offered to Meiji Jingu Shrine. It preserves confectionery committed to carefully selected ingredients and homemade red bean paste.', 'https://ohtakeya.jp', 'Shizuoka, Japan', 34.756664, 138.086265, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 134),
    ('Fuji Nishiki Shuzo', 'Shizuoka', 'Chubu', '1830', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenpo 1, a long-established sake brewery that has continued for over 190 years in Fujinomiya City. It continues brewing sake using Mt. Fuji''s spring water; its flagship brand "Fuji Nishiki" is loved as a representative local sake of Shizuoka. It also puts effort into brewery tours and local events.', 'https://www.fujinishiki.com', 'Shizuoka, Japan', 35.2694192, 138.5597174, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 125),
    ('Chojiya', 'Shizuoka', 'Chubu', '1596', 'food', 'food', 'savory', 'Tororo-jiru (grated yam soup) / Japanese cuisine', 'Founded in Keicho 1, a long-established shop that has served the famous "tororo-jiru" of the Tokaido''s Mariko post station for over 400 years. Known as a historic shop depicted in Utagawa Hiroshige''s ukiyo-e prints, it still welcomes many guests today with its traditional flavor and thatched-roof building.', 'https://www.chojiya.info', 'Shizuoka, Japan', 34.9502698, 138.3381281, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 104),
    ('Otaya Seikaten', 'Shizuoka', 'Chubu', '1880', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 13, a long-established Japanese sweets shop that has continued for over 140 years in Gotemba City. Committed to homemade red bean paste, it produces dorayaki, monaka, and seasonal fresh sweets. It continues confectionery loved by the community, preserving techniques and flavor handed down through five eras.', 'https://ootaya-gotemba.com', 'Shizuoka, Japan', 35.3158507, 138.9417799, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 193),
    ('Unagidokoro Suisei', 'Shizuoka', 'Chubu', '1871', 'food', 'food', 'savory', 'Eel cuisine', 'Founded in Meiji 4, a long-established eel restaurant that has operated in Mori Town for over 150 years. Using eel from Lake Hamana, it grills eel fragrantly with a secret sauce handed down for over 100 years. Together with a shop retaining Taisho-era charm, it carries its traditional flavor into the present.', 'https://suisei-unagi.com', 'Shizuoka, Japan', 34.841177, 137.933112, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 88),
    ('Marushichi Seicha', 'Shizuoka', 'Chubu', '1907', 'food', 'food', NULL, 'Tea processing', 'Founded in Meiji 40, a long-established tea company in Fujieda City. While preserving Shizuoka tea tradition, it also develops products such as its "Nanaya" brand highly-concentrated matcha gelato, which has drawn worldwide attention. It continues to promote tea culture in new forms.', 'https://www.marushichi-group.jp', 'Shizuoka, Japan', 34.8407638, 138.2153138, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.7, 160),
    ('Maruyama Seicha', 'Shizuoka', 'Chubu', '1908', 'food', 'food', NULL, 'Tea processing', 'Founded in Meiji 41, a long-established tea plantation and processing company in Kakegawa City. It handles everything from cultivation on its own tea fields through manufacturing and sales, promoting the appeal of Kakegawa tea in Japan and abroad. A long-established shop that keeps its commitment to quality.', 'https://www.maruyamaseicha.co.jp', 'Shizuoka, Japan', 34.752558, 138.032621, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.6, 35),
    ('Kaneju Farm', 'Shizuoka', 'Chubu', '1888', 'food', 'food', NULL, 'Tea processing', 'Founded in Meiji 21, a long-established tea plantation that has continued for over 130 years in Makinohara City. It handles everything from tea-leaf cultivation through processing, promoting the appeal of Shizuoka tea both domestically and overseas. It works on teamaking that blends tradition with innovation.', 'https://kaneju-farm.com', 'Shizuoka, Japan', 34.6732409, 138.1919574, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.6, 167),
    ('Mase', 'Shizuoka', 'Chubu', '1872', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 5, a leading long-established Japanese sweets shop in Atami-Ajiro. It produces sweets that evoke Izu''s local character, including its signature "Izu no Odoriko" and "Aizome." Valuing over 150 years of inherited tradition and craftsmanship, it is loved by many tourists and locals.', 'https://www.mase-jp.com', 'Shizuoka, Japan', 35.048186, 139.091308, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 117),
    ('Yamacho Suzuki Chojyu Shoten', 'Shizuoka', 'Chubu', '1880', 'food', 'food', NULL, 'Tea processing', 'Founded in Meiji 13, a long-established tea wholesaler that has continued for over 140 years in Mori Town. Centered on deep-steamed tea, it promotes the appeal of Shizuoka tea nationwide. A shop that continues high-quality teamaking drawing on years of honed judgment and processing technique.', 'https://yamachou.net', 'Shizuoka, Japan', 34.835133, 137.928924, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.7, 64),
    ('Marufuji Ichigen Shoten', 'Shizuoka', 'Chubu', 'c. 1900', 'food', 'food', NULL, 'Tea processing', 'A long-established tea wholesaler in Fujieda City with over 100 years of history. Working with local tea farmers, it sells a wide range of products including sencha, gyokuro, and hojicha. It carries on the skills of tea masters while continuing to convey the appeal of Shizuoka tea.', 'https://maru10tea.com', 'Shizuoka, Japan', 34.87075, 138.2502423, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.7, 64),
    ('Fuji Takasago Shuzo', 'Shizuoka', 'Chubu', '1830', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenpo 1, a long-established sake brewery that has continued for over 190 years in Fujinomiya City. Using Mt. Fuji''s spring water, it brews sake under the "Takasago" brand. Carrying on traditional technique, it is nationally known as a representative local sake of Shizuoka.', 'https://www.fuji-takasago.com', 'Shizuoka, Japan', 35.228472, 138.6065931, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 177),
    ('Shidaizumi Shuzo', 'Shizuoka', 'Chubu', '1882', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 15, a long-established sake brewery in Fujieda City. It continues brewing sake using spring water from the Seto River, earning high praise for its aromatic sake made with Shizuoka yeast. One of the area''s leading breweries, valuing tradition and quality.', 'https://www.shidaizumi.com', 'Shizuoka, Japan', 34.898472, 138.205408, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 136),
    ('Sakurai Kanseido', 'Nagano', 'Chubu', '1808', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Bunka 5, a leading long-established chestnut confectioner in Obuse Town. It is nationally known for chestnut yokan, kuri-kanoko, and other confections made with Shinshu chestnuts. It preserves traditional methods that value chestnut flavor while continuing to try new chestnut confections.', 'https://www.kanseido.co.jp', 'Nagano, Japan', 36.696863, 138.316733, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 87),
    ('Chikufudo', 'Nagano', 'Chubu', '1893', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 26. A leading chestnut confectionery shop representing Obuse, popular for chestnut okowa (glutinous rice) and kuri-kanoko. Committed to homemade chestnut paste, it continues to make products that showcase the ingredients'' natural character. One of Nagano Prefecture''s leading long-established brands.', 'https://www.chikufudo.com', 'Nagano, Japan', 36.6948291, 138.3155641, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 183),
    ('Obusedo', 'Nagano', 'Chubu', '1907', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in the late Meiji era, a long-established shop nationally known for kuri-kanoko and "Suzaku" made with chestnut paste. It carries Obuse''s chestnut culture into the present while sharing the region''s appeal through Japanese sweets.', 'https://www.obusedo.com', 'Nagano, Japan', 36.695307, 138.316161, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 166),
    ('Yawataya Isogoro', 'Nagano', 'Chubu', '1736', 'food', 'food', NULL, 'Food (shichimi togarashi spice)', 'Founded in Genbun 1. A long-established shichimi togarashi (seven-spice blend) shop born in front of Zenkoji Temple. Its shichimi, made from a secret blend, is a classic Nagano souvenir and has many fans nationwide as a fragrant seasoning.', 'https://www.yawataya.co.jp', 'Nagano, Japan', 36.6572785, 138.1876662, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 72),
    ('Yukawa Shuzoten', 'Nagano', 'Chubu', '1650', 'food', 'food', NULL, 'Sake brewing', 'Founded in Keian 3. A historic sake brewery that has continued for over 370 years in the Kiso region. Drawing on Kiso''s pure spring water and cold climate, it brews sake that values the natural savoriness of rice. Highly regarded for brewing that blends tradition with innovation.', 'https://www.yukawabrewery.com', 'Nagano, Japan', 35.9377356, 137.7843432, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 77),
    ('Senjo', 'Nagano', 'Chubu', '1866', 'food', 'food', NULL, 'Sake brewing', 'Founded in Keio 2, a long-established sake brewery that has continued for over 150 years in Ina City. Centered on sake made with Southern Alps spring water, it preserves traditional technique while also taking on new brewing approaches.', 'https://www.senjyo.co.jp', 'Nagano, Japan', 35.830374, 138.026985, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 117),
    ('Endo Shuzojo', 'Nagano', 'Chubu', '1864', 'food', 'food', NULL, 'Sake brewing', 'Founded in Genji 1. A brewery that has continued for over 160 years in Suzaka City, widely known for its "Keiryu" brand. It continues brewing sake using local rice and famous water, earning high praise both in Japan and abroad.', 'https://www.keiryu.jp', 'Nagano, Japan', 36.6534609, 138.3144874, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 178),
    ('EH Shuzo', 'Nagano', 'Chubu', '1865', 'food', 'food', NULL, 'Sake brewing', 'Founded in Keio 1. It brews sake drawing on the rich nature of Azumino City and spring water from the Northern Alps. Centered on its flagship brand "Suien," it brews sake with a distinctly Shinshu flavor.', 'https://www.eh-shuzo.com', 'Nagano, Japan', 36.2555595, 137.9236182, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 152),
    ('Tanakaya Shuzoten', 'Nagano', 'Chubu', '1665', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kanbun 5, a long-established sake brewery that has continued for over 350 years in Iiyama City. Its flagship brand "Mizuo" is known for its delicate flavor drawing on the nature of Oku-Shinano. It preserves tradition while pursuing quality improvement, supported by many sake fans.', 'https://www.mizuo.co.jp', 'Nagano, Japan', 36.853539, 138.3638536, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 184),
    ('Suyakame', 'Nagano', 'Chubu', '1902', 'food', 'food', 'savory', 'Miso / food', 'Founded in Meiji 35, a leading long-established miso brewery in front of Zenkoji Temple in Nagano City. It preserves Shinshu miso aged in wooden barrels, while also offering a wide range of fermented foods such as miso-pickles and oyaki dumplings. A popular shop carrying Shinshu''s fermentation culture into the present.', 'https://www.suyakame.co.jp', 'Nagano, Japan', 36.6512038, 138.1857772, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.7, 148),
    ('Sake no Hara Shoten (Shinshu Igeta Miso)', 'Nagano', 'Chubu', '1905', 'food', 'food', 'savory', 'Miso', 'A long-established miso brewery in Ueda City with over 110 years of history. Using local soybeans and Nagano-grown rice, it continues natural fermentation in old-fashioned wooden barrels. Its careful small-batch miso-making has earned wide support.', 'https://hara-igeta.jp', 'Nagano, Japan', 36.4178262, 138.2138857, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.7, 120),
    ('Marui Ito Shoten', 'Nagano', 'Chubu', 'c. 1910', 'food', 'food', 'savory', 'Miso / fermented foods', 'A long-established shop with over 100 years of history, continuing to make Shinshu miso in Chino City. Beyond miso, it also produces amazake, doburoku, and other fermented foods, preserving old-fashioned methods while actively developing new products.', 'https://www.misokengaku.jp', 'Nagano, Japan', 35.9876335, 138.1546964, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.7, 128),
    ('Wakamiya Kojiya', 'Nagano', 'Chubu', '1886', 'food', 'food', 'savory', 'Koji / miso', 'Founded in Meiji 19, a long-established koji specialty shop that has continued for over 130 years in Okaya City. Centered on handcrafted koji made by artisans, it also produces miso and amazake. One of Shinshu''s leading shops, proposing a "life with koji" while preserving traditional methods.', 'https://wakamiyakoujiya.com', 'Nagano, Japan', 36.065673, 138.060185, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.9, 94),
    ('Kamikochi Miso', 'Nagano', 'Chubu', '1909', 'food', 'food', 'savory', 'Miso', 'Founded in Meiji 42. A long-established maker that has brewed Shinshu miso for over 100 years. It offers a wide range of products for both commercial and household use, also focusing on developing processed and seasoned miso.', 'https://www.kamikoutimiso.co.jp', 'Nagano, Japan', 36.1874982, 137.8948197, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 157),
    ('Okashidokoro Miyamoto', 'Nagano', 'Chubu', 'c. 1920', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has continued for about 100 years in Ueda City. It carefully handmakes skewered dango, fresh dorayaki, and seasonal fresh sweets, actively using local ingredients. It continues community-rooted confectionery.', 'https://okashimiyamoto.wixsite.com/wagashi', 'Nagano, Japan', 36.404572, 138.258368, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 128),
    ('Nishizawaen', 'Nagano', 'Chubu', '1894', 'food', 'food', NULL, 'Tea shop', 'Founded in Meiji 27, a long-established tea shop that has continued for over 130 years in Nakano City. It offers original blends of carefully selected tea leaves from across Japan, tailored to Shinshu tastes. It preserves Japanese tea culture while offering a rich lineup of seasonal and gift items, loved by many local residents.', 'https://www.nishizawaen.co.jp', 'Nagano, Japan', 36.745921, 138.360943, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.6, 147),
    ('Danzuka', 'Nagano', 'Chubu', '1913', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 2, a long-established confectionery maker that has continued for over 100 years in Minamiminowa Village. It produces dango, daifuku, and manju, and has won awards at national confectionery expositions. It continues old-fashioned Japanese sweets-making using pure Southern Alps water.', 'https://danzuka.net', 'Nagano, Japan', 35.866479, 137.983424, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 136),
    ('Okashitsukasa Taguchi', 'Nagano', 'Chubu', 'c. 1910', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has continued for over 100 years in Kiso Town. Craftsmen carefully make signature confections such as Ontake monaka, soba manju, and kuri-kinton that draw on Kiso''s nature and culture. A shop long loved by both travelers and locals.', 'https://www.kashitaguchi.co.jp', 'Nagano, Japan', 35.8492203, 137.6955613, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 176),
    ('Maruyama Kashiho', 'Nagano', 'Chubu', '1909', 'food', 'food', 'sweet', 'Japanese & Western confectionery', 'Founded in Meiji 42, a long-established confectioner that has continued for over 100 years in Azumino City. It handles both Japanese and Western sweets, selling products that showcase seasonal ingredients. It continues community-rooted confectionery, loved across generations.', 'https://maruyama-kashiho.co.jp', 'Nagano, Japan', 36.3438011, 137.8849243, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 101),
    ('France Itaya', 'Nagano', 'Chubu', '1893', 'food', 'food', 'sweet', 'Japanese & Western confectionery', 'Founded in Meiji 26, a long-established confectioner in Ina City. It produces a wide range from Japanese sweets to Western confectionery and cakes, all handmade. For over 130 years it has supported the region''s celebrations and gift-giving culture as a leading Shinshu confectioner.', 'https://www.f-itaya.jp', 'Nagano, Japan', 35.845579, 137.963706, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 139),
    ('Sakenunoya Honkin Shuzo', 'Nagano', 'Chubu', '1756', 'food', 'food', NULL, 'Sake brewing', 'Founded in Horeki 6, a long-established sake brewery that has continued for over 260 years in Suwa City. Its flagship brand "Honkin" is brewed by hand using famous Suwa water and carefully selected sake rice. A leading Shinshu brewery preserving small-batch, high-quality sake brewing.', 'https://honkin.net', 'Nagano, Japan', 36.0418456, 138.12112, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 113),
    ('Osugiya Sohei', 'Niigata', 'Chubu', '1592', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Bunroku 1, known as one of Niigata Prefecture''s oldest Japanese sweets shops, located in Joetsu City. It began by making candy and now produces and sells traditional confections such as okina-ame and sasa-ame. A leading Niigata shop preserving techniques and flavor passed down for over 400 years.', 'https://ohsugiya.com/', 'Niigata, Japan', 37.1146845, 138.2451601, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 83),
    ('Mogamiya', 'Niigata', 'Chubu', '1871', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 4, a long-established Japanese sweets shop that has continued for over 150 years in Kashiwazaki City. It continues confectionery expressing the character of Echigo, led by its signature "Meiji Manju" and "Koshi no Araumi." Loved locally while spreading its traditional flavor nationwide.', 'https://www.mogamiya-niigata.com', 'Niigata, Japan', 37.3693186, 138.5531659, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 62),
    ('Nishiyama Seika', 'Niigata', 'Chubu', '1907', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 40, a long-established Japanese sweets shop that has continued for over 100 years in Teradomari, Nagaoka City. It produces representative Niigata local sweets such as sasa-dango, igaguri-dango, and miso manju, carefully preserving old-fashioned flavors.', 'https://www.nishiyamaseika.jp', 'Niigata, Japan', 37.6521712, 138.7748783, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 126),
    ('Chomeido Amepo', 'Niigata', 'Chubu', '1912', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 1, a long-established Japanese sweets shop in Nagaoka City. Its signature product, "Ame Monaka," is known as a creative confection combining mizuame syrup with monaka wafer. A popular shop that carefully continues confectionery one piece at a time.', 'https://amemonaka.jp', 'Niigata, Japan', 37.4452152, 138.8503263, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 59),
    ('Yonouduya', 'Niigata', 'Chubu', 'c. 1900', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A leading long-established Japanese sweets shop in the Yoshida district of Tsubame City. It produces confections that reflect the seasons, including its signature "Kumogakure" as well as yokan and monaka. A skilled shop highly regarded at national confectionery expositions.', 'https://www.yonouduya.co.jp', 'Niigata, Japan', 37.6896604, 138.8760295, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 190),
    ('Marutaya', 'Niigata', 'Chubu', '1868', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 1, a long-established Japanese sweets shop in Joetsu City. Committed to homemade red bean paste made only from Hokkaido azuki beans, it sells daifuku, dorayaki, and more. It also sells local sake, continuing community-rooted shopkeeping.', 'https://www.marutayasan.com', 'Niigata, Japan', 37.1857273, 138.3286331, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 118),
    ('Unomoriya', 'Niigata', 'Chubu', '1871', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in the Edo period, this long-established shop in Kamo City has continued making and selling confectionery since Meiji 4. Alongside Japanese and Western sweets, it also handles gifts and local sake, beloved as a presence supporting local culture.', 'https://www.unomoriya.co.jp', 'Niigata, Japan', 37.658559, 139.055363, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 140),
    ('Yoro Honpo Ikedaya', 'Niigata', 'Chubu', '1852', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kaei 5, a long-established Japanese sweets shop that has continued for over 170 years in Myoko City. Its signature confection "Yoro" has won awards at national confectionery expositions, and its refined flavor reflecting Echigo''s character has long been loved.', 'https://ikedaya-myoko.amebaownd.com', 'Niigata, Japan', 37.0290985, 138.2504577, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 155),
    ('Asahi Shuzo', 'Niigata', 'Chubu', '1830', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenpo 1, a long-established sake brewery in Nagaoka City. Nationally known for its flagship brand "Kubota," it continues brewing sake using Echigo''s famous water and carefully selected sake rice. A leading Niigata brewery that puts quality first.', 'https://www.asahi-shuzo.co.jp', 'Niigata, Japan', 37.3967972, 138.7745773, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 134),
    ('Osakaya', 'Niigata', 'Chubu', '1858', 'food', 'food', 'sweet', 'Japanese & Western confectionery', 'Founded in Ansei 5, a leading long-established confectioner in Niigata City. It has produced many representative Niigata sweets such as "Bandai Taiko" and "Nagare Ume." Handling both Japanese and Western confectionery, it has supported local life and gift-giving culture for over 160 years.', 'https://www.niigata-osakaya.com', 'Niigata, Japan', 37.9233739, 139.0452327, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 158),
    ('Tanabe Kashiho', 'Niigata', 'Chubu', '1927', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in the early Showa era, a long-loved confectioner in Kamo City. Its signature product "Tanabe no Karinto" is committed to being handmade and is loved by many fans. (Note: as it has not yet reached 100 years since founding, it is recommended as a future candidate for any "100+ years" listing.)', 'https://www.tanabekashiho.jp', 'Niigata, Japan', 37.6559566, 139.0637534, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 148),
    ('Ishizuka Shuzo (Himenoi)', 'Niigata', 'Chubu', '1907', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 40, a long-established sake brewery in Takayanagi-cho, Kashiwazaki City. Its flagship brand "Himenoi" is characterized by rich savoriness from the traditional four-stage brewing method using glutinous rice. Known as a skilled brewery that preserves sake-making reflecting the local terroir.', 'https://www.himenoi.com', 'Niigata, Japan', 37.2263103, 138.6384987, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 178),
    ('Imayotsukasa Shuzo', 'Niigata', 'Chubu', '1767', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiwa 4, a long-established sake brewery that has continued for over 250 years in Niigata City. Committed entirely to junmai sake, it spreads Niigata''s sake culture nationwide. Popular for brewery tours, it continues brewing that blends tradition with modernity.', 'https://imayotsukasa.com', 'Niigata, Japan', 37.9159616, 139.0718744, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 97),
    ('Minenohakubai Shuzo', 'Niigata', 'Chubu', '1635', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kanei 12, a long-established sake brewery boasting 390 years of history in Niigata City. Its flagship brand "Minenohakubai" is loved for its light yet richly savory flavor. It carefully preserves techniques cultivated over its long history.', 'https://minenohakubai.com', 'Niigata, Japan', 37.7571685, 138.8367732, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 91),
    ('Kirinzan Shuzo', 'Niigata', 'Chubu', '1843', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenpo 14, a long-established sake brewery in Aga Town. It brews sake using spring water from the Aganogawa river system and local rice; "Kirinzan" is highly regarded nationwide as a representative Niigata brand.', 'https://kirinzan.co.jp', 'Niigata, Japan', 37.6807303, 139.4606828, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 80),
    ('Takano Shuzo', 'Niigata', 'Chubu', '1899', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 32, a long-established sake brewery in Nishi Ward, Niigata City. Centered on its flagship brand "Koshiji Fubuki," it brews sake drawing on Echigo''s nature. Loved by many as a community-rooted brewery.', 'https://takano-shuzo.co.jp', 'Niigata, Japan', 37.8313033, 138.8912953, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 181),
    ('Nakagawa Shuzo (Koshi no Shirokari)', 'Niigata', 'Chubu', '1888', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 21, a long-established sake brewery that has continued for over 130 years in Nagaoka City. Its flagship brand "Koshi no Shirokari" is characterized by a refined flavor drawing on local sake rice and spring water from the Nishiyama mountains. It values old-fashioned handcrafting while pursuing quality improvement.', 'https://www.koshinohakugan.com', 'Niigata, Japan', 37.4997736, 138.7824045, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 83),
    ('Echigo Tsurukame', 'Niigata', 'Chubu', '1890', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 23, a long-established sake brewery in Nishikan Ward, Niigata City. Using spring water from Mt. Kakuda and sake rice from the Echigo Plain, it brews light, richly savory sake. It preserves traditional technique while spreading the appeal of Niigata sake at home and abroad.', 'https://echigotsurukame.com', 'Niigata, Japan', 37.7647035, 138.8678845, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 191),
    ('Kaganoi Shuzo', 'Niigata', 'Chubu', 'c. 1650', 'food', 'food', NULL, 'Sake brewing', 'A long-established sake brewery founded in the early Edo period, representing Itoigawa City. Its flagship brand "Kaganoi" is characterized by a gentle flavor using Northern Alps spring water. It rebuilt after a fire and continues brewing while preserving tradition.', 'https://kaganoi.co.jp/', 'Niigata, Japan', 37.0453676, 137.8590712, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 170),
    ('Ogawaya', 'Niigata', 'Chubu', '1893', 'food', 'food', 'savory', 'Salmon / seafood processing', 'Founded in Meiji 26, a long-established food maker in Niigata City. Centered on miso- and lees-pickled salmon, it produces traditional pickled fish. Through careful ingredient selection and aging, it delivers Niigata''s representative food culture nationwide.', 'https://www.niigata-ogawaya.co.jp', 'Niigata, Japan', 37.9201132, 139.0440413, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 132),
    ('Horikawa Sengyo', 'Niigata', 'Chubu', '1903', 'food', 'food', 'savory', 'Seafood processing', 'Founded in Meiji 36, a long-established company that continues seafood processing at Niigata Port. It produces products using fresh seafood such as fish paste products and dried fish, continuing to support local tables. It carries on a quality-first stance, working on safe, reliable products.', 'https://www.horikawa-corp.co.jp', 'Niigata, Japan', 37.991065, 139.2430773, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 90),
    ('Naniwaya Seika', 'Niigata', 'Chubu', '1923', 'food', 'food', 'savory', 'Rice crackers', 'Founded in Taisho 12, a leading long-established rice-cracker maker credited with creating the original "Kaki no Tane" (rice cracker). Its savory soy-sauce flavor and distinctive texture are loved nationwide, and it is known as the foundation of Niigata''s rice-cracker culture.', 'https://www.naniwayaseika.co.jp', 'Niigata, Japan', 37.4165541, 138.8301326, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 142),
    ('Tanakaya Honten', 'Niigata', 'Chubu', '1885', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 18, a leading long-established Japanese sweets shop in Niigata City. It continues making traditional Echigo confections such as sasa-dango and chimaki. Using carefully selected domestic ingredients and valuing old-fashioned craftsmanship, it delivers Niigata''s local flavors nationwide.', 'https://www.dangoya.com', 'Niigata, Japan', 37.9271984, 139.0568177, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 181),
    ('Naeba Shuzo', 'Niigata', 'Chubu', '1907', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 40, a long-established sake brewery that has continued for over 100 years in Tsunan Town. Drawing on the abundant snowmelt water unique to this heavy-snowfall region, it brews brands such as "Naebasan" and "Yuki no Mayu." It carries on the traditional techniques of Echigo toji brewmasters in community-rooted sake-making.', 'https://www.naebasan.com', 'Niigata, Japan', 37.0137006, 138.6514668, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 80),
    ('Obata Shuzo', 'Niigata', 'Chubu', '1892', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 25, a long-established sake brewery that has continued for over 130 years in Sado City. Its flagship brand "Manotsuru" has earned high praise at international sake competitions. It is also active in sake-making that utilizes local resources and in sustainable initiatives.', 'https://www.obata-shuzo.com', 'Niigata, Japan', 37.9634876, 138.3443251, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 169),
    ('Ryoguchiya Korekiyo', 'Aichi', 'Chubu', '1634', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kanei 11, a leading long-established Japanese sweets shop in Nagoya. Having developed as an official purveyor to the Owari domain, it is nationally known for "Sennari" and seasonal fresh sweets. With craftsmanship and aesthetic sense passed down for roughly 390 years, it continues to lead Nagoya''s Japanese sweets culture.', 'https://ryoguchiya-korekiyo.co.jp/', 'Aichi, Japan', 35.1742732, 136.9034249, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 188),
    ('Oguchiya', 'Aichi', 'Chubu', '1818', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Bunsei 1, a long-established Japanese sweets shop that has continued for over 200 years in Konan City. Its signature confection "Anfu Sankira" is a creative sweet wrapping refined smooth red bean paste in namafu (raw wheat gluten), loved by many. It preserves tradition while continuing seasonal confectionery.', 'https://www.ooguchiya.co.jp', 'Aichi, Japan', 35.3358985, 136.8715757, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 77),
    ('Furoen', 'Aichi', 'Chubu', '1848', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kaei 1, a long-established Japanese sweets shop that has continued for over 170 years in Naka Ward, Nagoya City. It carefully handmakes seasonal fresh sweets, yokan, and Nagoya specialty confections one by one. It preserves tradition while incorporating new sensibilities, loved by many.', 'https://www.furouen.co.jp', 'Aichi, Japan', 35.150678, 136.899249, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 194),
    ('Taihomaki Sohonpo Amebun Roho', 'Aichi', 'Chubu', 'Late Edo period', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has continued for over 150 years in Minamichita Town. Its specialty "Taihomaki" is known as a representative confection of the Chita Peninsula, and its kudzu-based sweets and kudzu ice cream are also popular. It preserves old-fashioned handcraft while sharing the region''s flavor.', 'https://amebun.com', 'Aichi, Japan', 34.79099, 136.9191705, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 179),
    ('Kadoya Kashiho', 'Aichi', 'Chubu', '1907', 'food', 'food', 'sweet', 'Japanese & Western confectionery', 'Founded in Meiji 40, a long-established confectioner that has continued for over 100 years in Iwakura City. Centered on Japanese sweets, it also handles Western confectionery, offering seasonal products. Loved across generations for its careful, community-rooted confectionery.', 'https://kadoyakashiho.com', 'Aichi, Japan', 35.281772, 136.875408, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 87),
    ('Kamisugi Shuzo', 'Aichi', 'Chubu', '1805', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunka 2, a long-established sake brewery that has continued for over 220 years in Anjo City. Its flagship brand "Kamisugi" is brewed using quality sake rice from Nishi-Mikawa and spring water from the Yahagi River system. It preserves traditional sake-making while continuing to brew sake loved by the community.', 'https://www.kamisugi.co.jp', 'Aichi, Japan', 34.9601131, 137.0922177, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 151),
    ('Sekiya Jozo', 'Aichi', 'Chubu', '1864', 'food', 'food', NULL, 'Sake brewing', 'Founded in Genji 1, a long-established sake brewery in Shitara Town. Its flagship brand "Horaisen" is highly regarded nationwide and known as a leader in ginjo sake brewing. It still carries on careful sake-making drawing on the nature and famous water of Oku-Mikawa.', 'https://www.houraisen.co.jp', 'Aichi, Japan', 35.093779, 137.5697168, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 50),
    ('Yamazaki Goshi Kaisha', 'Aichi', 'Chubu', '1903', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 36, a brewery that has continued for over 100 years in Nishio City. Its flagship brand "Sonno" is loved as a sake reflecting Mikawa''s local character. A leading community brewery preserving tradition while pursuing quality improvement.', 'https://www.sonnoh.co.jp', 'Aichi, Japan', 34.7929353, 137.1226958, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 76),
    ('Nakano Shuzo', 'Aichi', 'Chubu', '1844', 'food', 'food', NULL, 'Sake brewing / food', 'Founded in Koka 1, a long-established sake brewery in Handa City. Known for its flagship brand "Kunizakari," it produces not only sake but also plum wine and liqueurs. It also operates the "Kunizakari Sake Culture Museum" to convey fermentation culture, actively promoting the food culture of the Chita Peninsula.', 'https://www.nakanoshuzou.jp', 'Aichi, Japan', 34.8953447, 136.9349952, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 40),
    ('Minochu', 'Aichi', 'Chubu', '1854', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Ansei 1, a leading long-established Japanese sweets shop in Nagoya. Carrying on tradition associated with the Owari Tokugawa family, it continues to make refined sweets such as fresh sweets, yokan, and monaka. Its beautiful confections, valuing seasonal character, are highly regarded for tea ceremonies and gifts.', 'https://minochu.jp', 'Aichi, Japan', 35.1761865, 136.8941411, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 132),
    ('Ganso Shachi Monaka Honten', 'Aichi', 'Chubu', '1907', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 40. A long-established Japanese sweets shop known for "Shachi Monaka," modeled after the golden shachihoko dolphins of Nagoya Castle. Preserving a method and flavor unchanged for over 100 years, it is loved as a representative Nagoya souvenir.', 'https://shachimonaka.com', 'Aichi, Japan', 35.1562117, 136.895379, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 160),
    ('Kashikame', 'Aichi', 'Chubu', '1910', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 43, a long-established Japanese sweets shop in Inazawa City. It carefully produces sweets that reflect Owari''s local character, led by its signature "Matsuri Mochi." A community-rooted confectioner loved for over 100 years.', 'https://www.kashikame.com', 'Aichi, Japan', 35.2527818, 136.7906601, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 49),
    ('Yamamotoya Sohonke', 'Aichi', 'Chubu', '1925', 'food', 'food', 'savory', 'Dining (miso nikomi udon)', 'Founded in Taisho 14. A long-established shop known as the leading representative of Nagoya''s famous miso nikomi udon (miso-simmered udon). Characterized by a rich broth based on hatcho miso and firm noodles, it draws many visitors from Japan and abroad.', 'https://yamamotoya.co.jp', 'Aichi, Japan', 35.1659387, 136.9045562, 'https://images.unsplash.com/photo-1618841557871-b4664fbf0cb3?w=800&auto=format&fit=crop&q=80', 4.8, 149),
    ('Maruya Hatcho Miso', 'Aichi', 'Chubu', '1337', 'food', 'food', 'savory', 'Miso production', 'Founded in Engen 2, a long-established hatcho miso maker with over 680 years of history in Okazaki City. It preserves the traditional method of natural fermentation in wooden barrels, spreading hatcho miso culture at home and abroad. Factory tours are also popular.', 'https://www.8miso.co.jp', 'Aichi, Japan', 34.9566664, 137.151866, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.7, 124),
    ('Kakukyu Hatcho Miso', 'Aichi', 'Chubu', '1645', 'food', 'food', 'savory', 'Miso production', 'Founded in Shoho 2. A long-established maker that has continued producing hatcho miso in the area eight cho (about 870m) west of Okazaki Castle. It preserves the traditional method of aging for two summers and two winters, and conveys the appeal of fermentation culture through brewery tours and a museum.', 'https://www.kakukyu.jp', 'Aichi, Japan', 34.9578131, 137.1529958, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.9, 38),
    ('Kunpeki Shuzo', 'Aichi', 'Chubu', '1915', 'food', 'food', NULL, 'Sake brewing', 'Founded in Taisho 4, a long-established sake brewery that has continued for over 100 years in Konan City. Its flagship brand "Kunpeki" is popular as sake drawing on local rice and spring water from the Kiso River, continuing careful small-batch brewing.', 'https://kunpeki.co.jp', 'Aichi, Japan', 35.306818, 136.8792926, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 60),
    ('Bizenya', 'Aichi', 'Chubu', '1782', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Tenmei 2, a leading long-established Japanese sweets shop in Okazaki City. Its signature confections, including "Awayuki" and hand-grilled rice crackers, have been passed down through generations reflecting Mikawa''s local character. It preserves traditional methods while continuing seasonal confectionery.', 'https://www.bizenya.co.jp', 'Aichi, Japan', 34.9574353, 137.1703289, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 55),
    ('Kiyomemochi Sohonke', 'Aichi', 'Chubu', '1787', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Tenmei 7, a long-established shop that has continued for over 230 years in front of Atsuta Shrine. Its specialty "Kiyome Mochi" is characterized by soft mochi and refined smooth red bean paste, loved as a representative Nagoya confection. A shop that continues to preserve its traditional flavor.', 'https://www.kiyome.net', 'Aichi, Japan', 35.1242633, 136.9117297, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 124),
    ('Kawamuraya', 'Aichi', 'Chubu', '1924', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 13, a long-established Japanese sweets shop in Toyota City. It sells handmade Japanese sweets made with carefully selected ingredients, led by castella and dorayaki. Loved as a community-rooted confectioner, it is approaching its 100th anniversary. (Note: mind the listing timing for any "100+ years" page.)', 'https://www.t-kawamuraya.com/', 'Aichi, Japan', 35.0877429, 137.1597354, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 80),
    ('Mochigen', 'Aichi', 'Chubu', 'Late Edo period', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in the late Edo period, a long-loved mochi confectioner in Nagoya City. Centered on Nagoya''s famous uirou and mochi confections, it preserves old-fashioned flavor using carefully selected ingredients. Also popular for gifts and seasonal Japanese sweets.', 'https://mochigen.com', 'Aichi, Japan', 35.1771196, 136.9107978, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 88),
    ('Maruishi Jozo', 'Aichi', 'Chubu', '1690', 'food', 'food', NULL, 'Sake brewing', 'Founded in Genroku 3, a long-established sake brewery that has continued for over 330 years in Okazaki City. Its flagship brands "Nito" and "Mikawa Bushi" are highly regarded both in Japan and abroad. A leading Mikawa brewery that continues sake-making blending tradition with innovation.', 'https://014.co.jp', 'Aichi, Japan', 34.9559424, 137.1782937, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 96),
    ('Sawada Shuzo', 'Aichi', 'Chubu', '1848', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kaei 1, a long-established sake brewery in Tokoname City. Its flagship brand "Hakuro" is popular as a richly savory sake reflecting the character of the Chita Peninsula. It continues to refine quality while valuing old-fashioned handcrafting.', 'https://hakurou.com', 'Aichi, Japan', 34.8586548, 136.8595783, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 37),
    ('Kokonoe Mirin', 'Aichi', 'Chubu', '1772', 'food', 'food', 'sweet', 'Mirin (sweet cooking sake)', 'Founded in the Meiwa era, a long-established shop known as one of Japan''s oldest mirin producers, in Hekinan City. It produces authentic hon-mirin by traditional methods, led by its "Kokonoe Sakura" brand. Highly regarded nationwide as a seasoning maker supporting Japanese cuisine.', 'https://kokonoe.co.jp', 'Aichi, Japan', 34.8739846, 136.9808898, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 67),
    ('Kinchoen Sohonke', 'Gifu', 'Chubu', '1798', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kansei 10, a leading long-established Japanese sweets shop in Ogaki City. Its specialty "Kinchoen Manju" and its summer-only "Mizu Manju" (water manju) are known as representative Gifu confections. Drawing on Ogaki''s abundant groundwater, it continues to carefully make seasonal Japanese sweets.', 'https://www.wagashi-kinchouen.com', 'Gifu, Japan', 35.3658791, 136.6177521, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 128),
    ('Kanrindo Nagasakiya Honten', 'Gifu', 'Chubu', '1720', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kyoho 5, a long-established Japanese sweets shop that has continued for over 300 years in Gifu City. Its signature confections "Matsukaze" and "Miso Matsukaze" are widely known as traditional flavors handed down since the Edo period. It preserves historic methods while continuing to make Gifu''s representative sweets.', 'https://gifu-nagasakiya.com', 'Gifu, Japan', 35.4306864, 136.7657724, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 86),
    ('Tamaiya Honpo', 'Gifu', 'Chubu', '1908', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 41, a long-established Japanese sweets shop in Gifu City. Led by "Nobori Ayu," said to be the original ayu-fish-shaped confection, it produces seasonal fresh sweets and baked confections. Loved as a leading Gifu shop for confectionery expressing the atmosphere of the Nagara River.', 'https://www.tamaiyahonpo.com', 'Gifu, Japan', 35.4377466, 136.7725168, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 153),
    ('Kamekiso Honke', 'Gifu', 'Chubu', 'Meiji era', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established chestnut confectioner that has continued for over 100 years in Yaotsu Town. Led by kuri-kinton made with local chestnuts, it produces chestnut yokan and chestnut monaka. Its chestnut sweets, valuing the ingredients'' natural flavor, are popular as a representative autumn taste of Gifu.', 'https://kamekisohonke.com', 'Gifu, Japan', 35.475678, 137.1400994, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 181),
    ('Mochinobu', 'Gifu', 'Chubu', '1920', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 9, a long-established Japanese sweets shop that has continued for over 100 years in Kakamigahara City. It produces chestnut dorayaki, seasonal daifuku, and wakaayu confections, using local ingredients. Long loved as a community-rooted Japanese sweets shop.', 'https://mochinobu.com', 'Gifu, Japan', 35.3993813, 136.8358422, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 115),
    ('Watanabe Shuzojo', 'Gifu', 'Chubu', '1902', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 35, a long-established sake brewery in Ogaki City. It brews its flagship brand "Mino Nishiki," preserving sake-making with local rice and famous water for over 100 years. Gifu Prefecture''s only female toji (brewmaster) works on sake-making blending tradition with innovation.', 'https://minonishiki.com', 'Gifu, Japan', 35.3715068, 136.620982, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 38),
    ('Funasaka Shuzoten', 'Gifu', 'Chubu', '1703', 'food', 'food', NULL, 'Sake brewing', 'Founded in Genroku 16, a long-established sake brewery in Takayama City''s old townscape. It brews local Hida sake including its flagship brand "Miyama Giku," with a brewery tour and restaurant on site. Also a popular tourist spot in Hida-Takayama.', 'https://www.funasaka-shuzo.co.jp', 'Gifu, Japan', 36.140741, 137.2597061, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 115),
    ('Miwa Shuzo', 'Gifu', 'Chubu', '1837', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenpo 8, a long-established sake brewery in Ogaki City. It brews its flagship brand "Shirakawago" and is also nationally known for doburoku-style unfiltered sake. It carries on traditional technique while continuing distinctive sake-making.', 'https://www.miwashuzo.co.jp', 'Gifu, Japan', 35.3553645, 136.6104124, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 145),
    ('Tenryo Shuzo', 'Gifu', 'Chubu', '1680', 'food', 'food', NULL, 'Sake brewing', 'Founded in Enpo 8, a long-established sake brewery that has continued for over 340 years in Hagiwara-cho, Gero City. It brews sake using Hida''s spring water and carefully selected sake rice; its flagship brand "Tenryo" is highly regarded by sake fans nationwide.', 'https://www.tenryou.co.jp', 'Gifu, Japan', 35.8759662, 137.2090476, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 90),
    ('Inahoen', 'Gifu', 'Chubu', '1901', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 34, a long-established shop that has made Japanese sweets across three generations in Hida-Takayama. Alongside traditional confections drawing on Hida ingredients, its creative products such as "Shofuku Neko-ko Manju" are also popular. It preserves tradition while spreading the appeal of Hida-Takayama.', 'https://www.tohoen.com', 'Gifu, Japan', 36.1429, 137.2569639, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 187),
    ('Togetsuen', 'Gifu', 'Chubu', 'c. 1910', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has continued for over 100 years in Takehana-cho, Hashima City. Using homemade red bean paste cooked by an old-fashioned method, it produces daifuku, ayu confections, and misogi-dango. It values tradition while actively taking on new Japanese sweets.', 'https://togetuen.com', 'Gifu, Japan', 35.323726, 136.702548, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 179),
    ('Hayashi Shuzo', 'Gifu', 'Chubu', '1920', 'food', 'food', NULL, 'Sake brewing', 'Founded in Taisho 9, a long-established sake brewery that has continued for over 100 years in Kani City. Its flagship brand "Mino Tengu" is known for careful brewing using local rice. A skilled brewery continuing quality-focused small-batch sake-making.', 'https://minotengu.co.jp', 'Gifu, Japan', 35.413599, 137.0914993, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 38),
    ('Okuhida Shuzo', 'Gifu', 'Chubu', '1720', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kyoho 5, a long-established sake brewery in Kanayama-cho, Gero City. Using spring water from the Hida River system and Hida-grown sake rice, it brews brands such as "Hatsumidori." It values tradition passed down for over 300 years.', 'https://www.okuhida.co.jp', 'Gifu, Japan', 35.6626105, 137.157947, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 84),
    ('Nakashima Jozo', 'Gifu', 'Chubu', '1765', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiwa 2, a long-established sake brewery in Mizunami City. Its flagship brand "Kozaemon" is highly regarded by sake enthusiasts nationwide. It carries on traditional technique while also actively taking on new sake-making.', 'https://kozaemon.jp', 'Gifu, Japan', 35.3650046, 137.2599544, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 186),
    ('Miyozakura Jozo', 'Gifu', 'Chubu', '1893', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 26, a long-established sake brewery that has continued for over 130 years in Minokamo City. Its flagship brands "Tsushimaya" and "Miyozakura" are highly regarded at competitions in Japan and abroad. One of Gifu Prefecture''s leading breweries, blending tradition with innovation.', 'https://miyozakura.co.jp', 'Gifu, Japan', 35.438626, 137.014206, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 70),
    ('Mochiso', 'Gifu', 'Chubu', '1862', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Bunkyu 2, a long-established Japanese sweets shop that has continued for over 160 years in Ogaki City. Alongside mochi confections, sekihan, and seasonal fresh sweets, it is also known for its summer specialty "Mizuman Kori." It preserves confectionery drawing on Ogaki''s abundant groundwater, long loved by the community.', 'https://mochisou.com', 'Gifu, Japan', 35.3617796, 136.6170508, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 131),
    ('Shiraki Kosuke Shoten', 'Gifu', 'Chubu', '1835', 'food', 'food', NULL, 'Sake brewing', 'Founded in the late Edo period, a long-established sake brewery that has continued for over 160 years in Gifu City. Its flagship brand "Daruma Masamune" is nationally famous as a pioneer of long-aged sake. A leading Gifu brewery that continues to spread the appeal of aged sake worldwide.', 'https://www.daruma-masamune.co.jp', 'Gifu, Japan', 35.499023, 136.8359224, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 66),
    ('Watanabe Shuzoten', 'Gifu', 'Chubu', '1870', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 3, a long-established sake brewery in Furukawa-cho, Hida City. Its flagship brand "Horai" is a popular brand highly regarded at the National New Sake Awards. It preserves sake-making drawing on Hida''s nature and tradition while actively taking on new challenges.', 'https://www.sake-hourai.co.jp', 'Gifu, Japan', 36.2353128, 137.1863258, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 119),
    ('Kaba Shuzojo', 'Gifu', 'Chubu', '1700', 'food', 'food', NULL, 'Sake brewing', 'Founded in the Genroku era, a long-established sake brewery that has continued for over 320 years in Furukawa-cho, Hida City. With "Shirayumi" as its flagship brand, it carries on sake-making drawing on Hida''s cold climate. Its historic brewery is a landmark of the Hida-Furukawa townscape.', 'https://www.yancha.com/', 'Gifu, Japan', 36.2348675, 137.1870347, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 182),
    ('Hakusen Shuzo', 'Gifu', 'Chubu', '1855', 'food', 'food', 'sweet', 'Hon-mirin / sake brewing', 'Founded in Ansei 2, a long-established brewer in Kawabe Town. Its "Fukuraijun Three-Year Aged Hon-Mirin" is highly regarded by chefs nationwide. It preserves old-fashioned methods, continuing hon-mirin production aged over time.', 'https://www.hakusenshuzou.jp/', 'Gifu, Japan', 35.4876713, 137.0682899, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 158),
    ('Gyokusendo Shuzo', 'Gifu', 'Chubu', '1806', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunka 3, a long-established sake brewery that has continued for over 200 years in Yoro Town. Its flagship brand "Reisen" is known for its refined flavor using spring water from the Yoro mountains and carefully selected sake rice. It has won numerous awards at competitions in Japan and abroad.', 'https://www.gyokusendo.jp/', 'Gifu, Japan', 35.3083296, 136.5608853, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 134),
    ('Tomoan Kashi Kobo', 'Gifu', 'Chubu', '1921', 'food', 'food', 'sweet', 'Japanese sweets / food manufacturing', 'Founded in Taisho 10, a long-established Japanese sweets maker in Ena City. Using natural water, it produces warabimochi, yokan, and other Japanese sweets, also offering a wide range of commercial-use products. It preserves traditional methods while focusing on hygiene management and quality improvement.', 'https://dangoya.co.jp/', 'Gifu, Japan', 35.5160788, 137.2978432, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 114),
    ('Kasho Toyodaya', 'Gifu', 'Chubu', '1926', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Showa 1, a long-established Japanese sweets shop in Kitagata-cho, Motosu District. Led by the local confection "Myogabochi," it handmakes seasonal Japanese sweets one by one. A locally loved shop continuing to convey the region''s traditional culture through Japanese sweets.', 'https://www.toyodaya.net', 'Gifu, Japan', 35.4189933, 136.6914678, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 166),
    ('Wakabayashiya Sohonke', 'Toyama', 'Chubu', '1868', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 1, a leading long-established Japanese sweets shop in Oyabe City. Craftsmen carefully finish seasonal fresh sweets, monaka, and manju one by one. It preserves traditional technique and an unchanging flavor, long loved locally.', 'https://wakabayashiyasouhonke.jp', 'Toyama, Japan', 36.671537, 136.8682264, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 139),
    ('Hikiami Kogetsudo', 'Toyama', 'Chubu', '1919', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 8, a long-established Japanese sweets shop in Toyama City. Known for seasonal fresh sweets and creative confections, it continues confectionery blending traditional technique with modern sensibility. One of Toyama''s leading Japanese sweets shops.', 'https://www.hikiami.co.jp', 'Toyama, Japan', 36.6903349, 137.140089, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 37),
    ('Kasho Kajiwaya', 'Toyama', 'Chubu', '1868', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 2, a long-established Japanese sweets shop in Fukumitsu, Nanto City. It produces confections using local ingredients, including mizu-yokan, monaka, and Nanto baumkuchen. Loved by the community for techniques passed down for over 150 years.', 'https://www.kajiwaya.com', 'Toyama, Japan', 36.558929, 136.87232, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 100),
    ('Hayashiseido Honten', 'Toyama', 'Chubu', 'Early Meiji era', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'A long-established Japanese sweets shop that has continued since the early Meiji era in Yatsuo-machi, Toyama City. Its specialty "Owara Tamaten" is known as a representative confection of Ecchu-Yatsuo. It still carefully makes traditional Japanese sweets using local ingredients.', 'https://tamaten-rsd.com', 'Toyama, Japan', 36.5913237, 137.1415261, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 183),
    ('Omura Kashiho', 'Toyama', 'Chubu', '1918', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 7, a long-established Japanese sweets shop in Asahi Town. Its signature confection "Hisui Yokan" is known as a representative sweet of Toyama Prefecture. It expresses local nature and culture through Japanese sweets and boasts numerous awards.', 'https://www.oomurakashiho.com', 'Toyama, Japan', 36.95709, 137.5663717, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 179),
    ('Masuda Shuzoten', 'Toyama', 'Chubu', '1893', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 26, a long-established sake brewery in the Iwase district of Toyama City. Its flagship brand "Masuizumi" is highly regarded by sake fans nationwide. Its sake-making, blending tradition with innovation, is also popular overseas.', 'https://www.masuizumi.co.jp', 'Toyama, Japan', 36.7552278, 137.2292493, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 173),
    ('Yoshinotomo Shuzo', 'Toyama', 'Chubu', '1877', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 10, a long-established sake brewery that has continued for over 140 years in Fuchu-machi, Toyama City. Its flagship brand "Yoshinotomo" was an early adopter of junmai sake-making, preserving sake-making that draws on Toyama''s rice and water.', 'https://yoshinotomo.com/', 'Toyama, Japan', 36.6410315, 137.1599539, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 78),
    ('Uozu Shuzo', 'Toyama', 'Chubu', '1925', 'food', 'food', NULL, 'Sake brewing', 'Its flagship brand "Honami" is a local sake brewed using spring water from the Northern Alps and Toyama-grown rice. It continues careful, community-rooted sake-making.', 'https://uozushuzo.co.jp/', 'Toyama, Japan', 36.8181224, 137.404015, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 85),
    ('Ginnanmochi Honpo Ogaya', 'Toyama', 'Chubu', '1872', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 5, a long-established Japanese sweets shop in Himi City. Its specialty "Ginnan Mochi" is characterized by the refined flavor of kneaded ginkgo nuts, known as a representative local confection of Ecchu. A shop that preserves methods passed down through generations.', 'https://www.ginnanmoti-ogaya.com', 'Toyama, Japan', 36.856406, 136.987692, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 165),
    ('Nakao Seigetsudo', 'Toyama', 'Chubu', '1875', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 8, a leading long-established Japanese sweets shop in Takaoka City. Craftsmen carefully finish seasonal Japanese sweets, led by its signature dorayaki "Seigetsu" and confection "Nakamochi." Highly regarded not only locally but nationwide.', 'https://www.seigetsudou.co.jp', 'Toyama, Japan', 36.7490182, 136.9952732, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 149),
    ('Minamoto', 'Toyama', 'Chubu', '1908', 'food', 'food', 'savory', 'Trout sushi / ekiben (station bento)', 'Founded in Meiji 41, a leading long-established trout-sushi shop in Toyama City. Its "Masu no Sushi," loved as a station bento, is nationally famous, and the "Masu no Sushi Museum" now lets visitors observe the production process. A leading shop representing Toyama''s food culture.', 'https://www.minamoto.co.jp', 'Toyama, Japan', 36.627272, 137.203739, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 143),
    ('Wakatsuru Shuzo', 'Toyama', 'Chubu', '1862', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunkyu 2, a long-established sake brewery that has continued for over 160 years in Tonami City. It brews its flagship brands "Naekaya" and "Wakatsuru," highly regarded as a leading Hokuriku brewery. A whiskey distillery is also on site, continuing new challenges.', 'https://www.wakatsuru.co.jp', 'Toyama, Japan', 36.6551788, 136.969764, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 41),
    ('Tateyama Shuzo', 'Toyama', 'Chubu', '1835', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenpo 6, a long-established sake brewery in Tonami City. Its flagship brand "Tateyama" is widely loved within Toyama Prefecture and has many fans nationwide for its light, dry flavor. A leading brewery still carrying on traditional sake-making.', 'https://www.sake-tateyama.com', 'Toyama, Japan', 36.6063966, 136.9866573, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 101),
    ('Ginban Shuzo', 'Toyama', 'Chubu', '1910', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 43, a long-established sake brewery in Kurobe City. Its flagship brand "Ginban" is characterized by a crisp flavor using Northern Alps spring water. It has supported Toyama''s local sake culture for over 100 years.', 'https://ginban.co.jp', 'Toyama, Japan', 36.8749715, 137.4712278, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 137),
    ('Narimasa Shuzo', 'Toyama', 'Chubu', '1894', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 27, a long-established sake brewery in Nanto City. Its flagship brand "Narimasa" is known as a sake using local rice and pure spring water. It preserves careful small-batch sake-making.', 'https://www.narimasa.co.jp/', 'Toyama, Japan', 36.544858, 136.839317, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 185),
    ('Dosho Kombu', 'Toyama', 'Chubu', '1916', 'food', 'food', 'savory', 'Kombu / food manufacturing', 'Founded in Taisho 5, a kombu (kelp) specialty shop that has continued for over 100 years in Toyama City. It carefully selects Hokkaido-grown kombu, producing and selling tororo kombu, dashi kombu, and processed kombu products. A long-established shop supporting Toyama''s kombu culture, offering products from household to gift use.', 'https://dosho-kombu.jp', 'Toyama, Japan', 36.6969151, 137.2264218, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 66),
    ('Okudaya', 'Toyama', 'Chubu', '1861', 'food', 'food', 'savory', 'Fresh fish / kombu-cured fish', 'Founded in Bunkyu 1, a long-established fresh-fish shop in Toyama City. Known for kombu-cured fish and catering dishes made with fresh fish caught in Toyama Bay. With craftsmanship passed down across five generations, it delivers Toyama''s distinctive flavors nationwide.', 'https://www.kobujime.jp', 'Toyama, Japan', 36.6326998, 137.2064434, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 176),
    ('Hono Kojiten', 'Toyama', 'Chubu', '1906', 'food', 'food', 'sweet', 'Koji / miso / amazake', 'Founded in Meiji 39, a long-established koji shop that has continued for over 100 years in Nanto City. It produces fermented foods such as rice koji, shio-koji, miso, and amazake, preserving old-fashioned koji-making that draws on local rice. A leading Toyama shop carrying fermentation culture into the present.', 'https://www.hounokoujiten.jp', 'Toyama, Japan', 36.5608695, 136.870704, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 137),
    ('Nannichi Miso Shoyu', 'Toyama', 'Chubu', '1889', 'food', 'food', 'savory', 'Miso / soy sauce', 'A long-established brewer in Toyama City boasting over 100 years since founding. Using Toyama-grown rice and domestic soybeans, it produces miso, soy sauce, and koji products. Highly regarded for products blending traditional fermentation technique with modern quality control.', 'https://www.nannichi.co.jp', 'Toyama, Japan', 36.696377, 137.23658, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.9, 194),
    ('Nakaroku Jozomoto', 'Toyama', 'Chubu', '1920', 'food', 'food', 'savory', 'Miso / soy sauce', 'Founded in Taisho 9, a long-established brewer in Tonami City. Centered on local ingredients, it produces naturally fermented miso, soy sauce, and koji products. It preserves traditional methods while continuing to make fermented foods that support household tables.', 'https://www.nakaroku.com', 'Toyama, Japan', 36.7805548, 137.0845471, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 109),
    ('Tamaasahi Shuzo', 'Toyama', 'Chubu', '1808', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunka 5, a long-established sake brewery in Yatsuo-machi, Toyama City. Its flagship brand "Tamaasahi" is a distinguished Toyama sake brewed using local sake rice and famous water. With over 200 years of history, it works on sake-making blending tradition with innovation.', 'https://www.tamaasahi.jp', 'Toyama, Japan', 36.577346, 137.136229, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 163),
    ('Fumigiku Shuzo', 'Toyama', 'Chubu', '1916', 'food', 'food', NULL, 'Sake brewing', 'Founded in Taisho 5, a long-established sake brewery in Toyama City. Its flagship brand "Haneya" has won numerous awards at sake competitions in Japan and abroad. Committed to traditional handcrafting, it continues high-quality sake-making.', 'https://fumigiku.co.jp', 'Toyama, Japan', 36.721022, 137.2011802, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 71),
    ('Takazawa Shuzojo', 'Toyama', 'Chubu', '1872', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 5, a long-established sake brewery in Himi City. Its flagship brand "Ariiso Akebono" is loved as a sake that pairs well with the seafood of Toyama Bay. For over 140 years it has continued sake-making reflecting Himi''s local character.', 'https://ariiso-akebono.jp/', 'Toyama, Japan', 36.8655367, 136.984658, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 131),
    ('Fuwa Fukujudo', 'Toyama', 'Chubu', '1897', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 30, a long-established Japanese sweets shop in Takaoka City. Its signature confection "Kanoko Mochi" is known as a representative Japanese sweet of Toyama Prefecture. Valuing carefully selected ingredients and craftsmanship, it continues to offer seasonal Japanese sweets.', 'https://www.kanokomochi.co.jp/', 'Toyama, Japan', 36.7323695, 137.0151882, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 38),
    ('Morihachi', 'Ishikawa', 'Chubu', '1625', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kanei 2, one of Kanazawa''s leading long-established shops with roughly 400 years of history as official confectioner to the Kaga domain. Its signature confection "Chosei-den" is known as one of Japan''s three great confections, carrying Kaga''s confectionery culture into the present. It preserves tradition while continuing to make Japanese sweets rich with seasonal character.', 'https://www.morihachi.co.jp', 'Ishikawa, Japan', 36.5694444, 136.6638889, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 75),
    ('Enpachi', 'Ishikawa', 'Chubu', '1737', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Genbun 2, a leading long-established Japanese sweets shop in Hakusan City. Its specialty "Ankoromochi" is made with Mt. Hakusan''s spring water and carefully selected ingredients, nationally known as a representative confection of Ishikawa Prefecture. It has preserved an unchanging flavor for roughly 280 years.', 'https://www.enpachi.com', 'Ishikawa, Japan', 36.522428, 136.558857, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 153),
    ('Rakugan Moroeya', 'Ishikawa', 'Chubu', '1849', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kaei 2. A leading shop representing Kanazawa''s famous rakugan (dried sugar confection), carrying Kaga confections such as "Hojo Kashi" and "Hana Usagi" into the present. It preserves traditional methods while continuing Japanese sweets-making suited to modern life.', 'https://moroeya.co.jp', 'Ishikawa, Japan', 36.5544244, 136.6474679, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 120),
    ('Nakashima', 'Ishikawa', 'Chubu', '1881', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 14, a long-established Japanese sweets shop that has operated near Kenrokuen Garden. It produces traditional confections using local ingredients, including Kaga kurumi mochi and monaka. A shop long loved by tourists and local residents alike.', 'https://www.wagashi-nakashima.com', 'Ishikawa, Japan', 36.5657514, 136.6637093, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 155),
    ('Koshiyama Kanseido', 'Ishikawa', 'Chubu', '1888', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 21, a long-established Japanese sweets shop in Kanazawa City. Its signature confection "Yakiman" and fresh sweets are characterized by delicate beauty reflecting Kaga''s four seasons. Also well regarded for tea-ceremony confections, it continues to support Kanazawa''s Japanese sweets culture.', 'https://www.koshiyamakanseido.jp/', 'Ishikawa, Japan', 36.5714268, 136.6618494, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 88),
    ('Fukumitsuya', 'Ishikawa', 'Chubu', '1625', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kanei 2, a long-established sake brewery that has continued for roughly 400 years in Kanazawa City. It brews its flagship brands "Kuro-obi," "Kagatobi," and "Fuku Masamune," highly regarded at home and abroad for its commitment to junmai sake. It also develops food and cosmetic products drawing on its fermentation technology.', 'https://www.fukumitsuya.co.jp', 'Ishikawa, Japan', 36.5537054, 136.6723403, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 50),
    ('Shatai Shuzo', 'Ishikawa', 'Chubu', '1823', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunsei 6, a long-established sake brewery in Hakusan City. Its flagship brand "Tengumai" is nationally known as a fine sake made by the yamahai brewing method. One of Ishikawa Prefecture''s leading breweries, continuing high-quality sake-making while valuing traditional technique.', 'https://www.tengumai.co.jp', 'Ishikawa, Japan', 36.493313, 136.576847, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 106),
    ('Nakamura Shuzo', 'Ishikawa', 'Chubu', '1823', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunsei 6, a long-established sake brewery in Kanazawa City. Its flagship brands "Nichiei" and "Kaga Hyakumangoku" are brewed using sake rice from the Kaga plain and pure spring water. It preserves techniques passed down for over 200 years.', 'https://www.nakamura-shuzou.co.jp', 'Ishikawa, Japan', 36.5175197, 136.5974184, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 110),
    ('Tanakaya', 'Ishikawa', 'Chubu', '1905', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 38, a long-established Japanese sweets shop in Hakusan City. Craftsmen carefully continue making seasonal fresh sweets, baked confections, and monaka. Preserving old-fashioned technique while staying close to the community, it has been loved for over 100 years.', 'https://tanakaya.co.jp', 'Ishikawa, Japan', 36.5229252, 136.5670568, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 148),
    ('Wagashi Murakami', 'Ishikawa', 'Chubu', '1911', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 44, a leading long-established Japanese sweets shop in Kanazawa City. Committed to homemade red bean paste, it offers a wide range from traditional confections to creative Japanese sweets. Its beautiful confectionery reflecting the four seasons is highly popular within and beyond the prefecture.', 'https://www.wagashi-murakami.com', 'Ishikawa, Japan', 36.544606, 136.6370596, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 101),
    ('Umeya Tsunegoro', 'Ishikawa', 'Chubu', '1915', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 4, a long-established Japanese sweets shop that has continued for over 110 years in Nanao City. Led by its signature brown-sugar manju and soybean candy, it produces Japanese sweets that evoke Noto''s local character. It still carefully preserves craftsmanship passed down through generations.', 'https://www.umeyatsunegoro.jp', 'Ishikawa, Japan', 37.0456522, 136.9668516, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 44),
    ('Okashitsukasa Mifuku', 'Ishikawa', 'Chubu', '1908', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 41, a long-established Japanese sweets shop in Komatsu City. It produces fresh sweets and baked confections expressing Kaga''s four seasons, also well regarded for tea-ceremony confections. Long loved locally, it continues confectionery valuing tradition and quality.', 'https://okashi-mifuku.com/index.html', 'Ishikawa, Japan', 36.5546825, 136.681604, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 118),
    ('Shikano Shuzo', 'Ishikawa', 'Chubu', '1819', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunsei 2, a long-established sake brewery in Kaga City. Its flagship brand "Joki-gen" is known as a fine sake highly regarded at the National New Sake Awards. Using high-quality rice from the Kaga plain and spring water from sacred Mt. Hakusan, it preserves traditional sake-making.', 'https://www.jokigen.co.jp', 'Ishikawa, Japan', 36.3250128, 136.3710515, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 37),
    ('Kazuma Shuzo', 'Ishikawa', 'Chubu', '1869', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 2, a long-established sake brewery that has continued for over 150 years in Noto Town. Its flagship brand "Chikuha" is known as a sake reflecting Noto''s local character, also popular for how well it pairs with local ingredients. It values community-rooted sake-making.', 'https://chikuha.co.jp', 'Ishikawa, Japan', 37.3082782, 137.1508689, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 175),
    ('Yamato Soy Sauce & Miso', 'Ishikawa', 'Chubu', '1911', 'food', 'food', 'savory', 'Miso / soy sauce / fermented foods', 'Founded in Meiji 44, a leading long-established fermented-food maker in Ono-machi, Kanazawa City. It produces a wide range of products including soy sauce, miso, amazake, and salted koji, also promoting the appeal of fermentation culture through its "Fermented Food Beauty Dining" restaurant, among other ventures.', 'https://www.yamato-soysauce-miso.co.jp', 'Ishikawa, Japan', 36.6133069, 136.6077757, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.7, 148),
    ('Naogen Shoyu', 'Ishikawa', 'Chubu', '1825', 'food', 'food', 'savory', 'Soy sauce / seasonings', 'Founded in Bunsei 8. A long-established soy sauce maker that has continued for roughly 200 years in Ono, Kanazawa City. As a leading producer of the traditional "Ono Shoyu," it makes whole-soybean soy sauce, dashi soy sauce, ponzu, and kaburazushi. Its historic brewery, now also a shop and café, is a popular destination.', 'https://www.naogen.co.jp', 'Ishikawa, Japan', 36.6118037, 136.6042254, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 121),
    ('Torii Shoyu-ten', 'Ishikawa', 'Chubu', '1908', 'food', 'food', 'savory', 'Soy sauce / miso', 'Founded in Meiji 41, a long-established soy sauce brewery in Ono-machi, Kanazawa City. It preserves natural fermentation in cedar barrels, producing dark and light soy sauce and miso. Valuing old-fashioned fermentation technique, it is loved as a presence supporting Kanazawa''s food culture.', 'https://www.toriishouyu.jp/', 'Ishikawa, Japan', 37.0469559, 136.9629914, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.6, 115),
    ('Kaga Fu Fumuroya', 'Ishikawa', 'Chubu', '1865', 'food', 'food', NULL, 'Fu (wheat gluten) / food manufacturing', 'Founded in Keio 1, a leading long-established fu (wheat gluten) specialty shop in Kanazawa City. It produces and sells yaki-fu, nama-fu, and "Takara no Fu," all essential to Kaga cuisine. With technique and beautiful product-making passed down for over 160 years, it spreads Kaga fu culture nationwide.', 'https://www.fumuroya.co.jp', 'Ishikawa, Japan', 36.5719491, 136.6578517, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 94),
    ('Kinjoro', 'Ishikawa', 'Chubu', '1890', 'food', 'food', NULL, 'Ryotei restaurant / inn', 'Founded in Meiji 23. A leading long-established ryotei-inn in Kanazawa. In a space blending Kaga cuisine, traditional architecture, gardens, and art crafts, it has welcomed many cultural figures and guests from Japan and abroad. A prestigious shop carrying Kanazawa''s food culture into the present.', 'https://www.kinjohro.co.jp', 'Ishikawa, Japan', 36.5703167, 136.6642806, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.8, 113),
    ('Ryotei Matsuya', 'Ishikawa', 'Chubu', 'c. 1900', 'food', 'food', NULL, 'Ryotei restaurant', 'A long-established ryotei that has continued for over 100 years in Ataka-machi, Komatsu City. It serves Kaga cuisine centered on seasonal seafood landed at Ataka fishing port, having grown alongside the history of a port town shaped by the Kitamaebune shipping culture. Its building, a registered tangible cultural property, is also part of its appeal.', 'https://www.matsu-ya.jp', 'Ishikawa, Japan', 36.421145, 136.421067, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 114),
    ('Nakahatsu Shoten', 'Ishikawa', 'Chubu', '1896', 'food', 'food', 'savory', 'Miso / soy sauce', 'Founded in Meiji 29, a long-established brewer in Komatsu City. It continues making naturally fermented miso and soy sauce by old-fashioned methods. A fermented-food maker supporting local tables, boasting roughly 200 years of history.', 'https://nakahatsu.jp/', 'Ishikawa, Japan', 36.5544061, 136.6473192, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 81),
    ('Kaga Kashitsukasa Goshuin', 'Ishikawa', 'Chubu', '1908', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 41, a long-established Japanese sweets shop in Komatsu City. Centered on traditional Kaga fresh sweets and baked confections, it produces beautiful seasonal Japanese sweets. Deeply connected to tea-ceremony culture, it is loved by the local community.', 'https://www.goshuin.co.jp', 'Ishikawa, Japan', 36.4023695, 136.449342, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 184),
    ('Takazawa Candle', 'Ishikawa', 'Chubu', '1892', 'shop', 'shop', NULL, 'Japanese candles', 'Founded in Meiji 25, a long-established Japanese-candle shop in Nanao City. Though not a food shop, it is highly regarded at home and abroad as a representative traditional industry of Ishikawa Prefecture. It continues to handcraft Japanese candles from plant-based materials, carrying Noto''s culture into the present.', 'https://takazawacandle.jp/index.html', 'Ishikawa, Japan', 37.0464176, 136.9640586, 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=800&auto=format&fit=crop&q=80', 4.6, 103),
    ('Okashitsukasa Daikokuya', 'Fukui', 'Chubu', '1630', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kanei 7, a leading long-established Japanese sweets shop in Sabae City. Widely known for the Fukui confection "Saikato" and the winter specialty "mizu-yokan," it has preserved traditional flavor for roughly 400 years. Loved by many for confectionery using local ingredients and products that evoke the four seasons.', 'https://www.saikatou.com', 'Fukui, Japan', 35.9462425, 136.1856176, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 107),
    ('Habutaemochi Sohonpo Matsuokaken', 'Fukui', 'Chubu', '1897', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 30. A long-established Japanese sweets shop known as the birthplace of the Fukui confection "Habutae Mochi." It preserves the traditional method while producing habutae mochi, monaka, and dorayaki, continuing to deliver Fukui''s representative confection nationwide.', 'https://www.habutae-matuokaken.com', 'Fukui, Japan', 36.0631465, 136.213874, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 89),
    ('Okashitsukasa Eitaro', 'Fukui', 'Chubu', '1923', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 12. A leading long-established Japanese sweets shop in Fukui City, producing habutae mochi, mizu-yokan, and seasonal fresh sweets. Its confectionery, blending technique passed down across four generations with modern sensibility, is highly regarded.', 'https://www.eitaro.co.jp', 'Fukui, Japan', 36.0829249, 136.2104361, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 96),
    ('Osaya', 'Fukui', 'Chubu', '1912', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 1. A long-established Japanese sweets shop associated with Maruoka Castle, now operating in Fukui City. Led by its signature dorayaki, it carefully continues to hand-make Japanese sweets preserving old-fashioned methods, long loved by the community.', 'https://www.osaya.jp', 'Fukui, Japan', 36.1188608, 136.2498929, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 108),
    ('Ippongi Kubo Honten', 'Fukui', 'Chubu', '1902', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 35, a long-established sake brewery in Katsuyama City. Its flagship brands "Ippongi" and "Denshin" are known as representative local sakes of Fukui. Using snowmelt water and quality sake rice from Oku-Echizen, it continues sake-making that pursues quality while preserving tradition.', 'https://www.ippongi.co.jp', 'Fukui, Japan', 36.063161, 136.500203, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 55),
    ('Kokuryu Shuzo', 'Fukui', 'Chubu', '1804', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunka 1, a long-established sake brewery in Eiheiji Town. Its flagship brands "Kokuryu" and "Kuzuryu" are highly regarded in Japan and abroad. Known as a pioneer of ginjo sake, it is a leading Fukui brewery driving Japan''s sake culture.', 'https://www.kokuryu.co.jp', 'Fukui, Japan', 36.0913513, 136.299012, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 67),
    ('Nanbu Shuzojo', 'Fukui', 'Chubu', '1901', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 34, a long-established sake brewery in Ono City. Its flagship brand "Hanagaki" is brewed using groundwater from Echizen-Ono, selected as one of Japan''s Top 100 Famous Waters. It preserves traditional technique while continuing sake-making reflecting the local terroir.', 'https://www.hanagaki.co.jp', 'Fukui, Japan', 35.9849979, 136.4898133, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 69),
    ('Iseya Yohei', 'Fukui', 'Chubu', '1830', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Tenpo 1 (1830), a leading long-established Japanese sweets shop in Obama City. It continues making its specialty kudzu manju, decchi yokan, and daifuku by old-fashioned methods. Using "Unjosui," one of the Heisei-era Top 100 Famous Waters, it is loved by many fans for confectionery that values the ingredients'' natural character.', 'https://www.iseya-yohei.jp', 'Fukui, Japan', 35.4997578, 135.7461316, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 158),
    ('Yasumoto Shuzo', 'Fukui', 'Chubu', '1853', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kaei 6, a long-established sake brewery in Fukui City. Its flagship brand "Hakugakusen" is characterized by a delicate flavor using Fukui-grown sake rice and spring water from the Kuzuryu River system. With over 200 years of history, it also takes on sake-making suited to modern food culture.', 'https://www.hakugakusen.jp/', 'Fukui, Japan', 36.0156127, 136.2768408, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 194),
    ('Kubota Shuzo', 'Fukui', 'Chubu', '1753', 'food', 'food', NULL, 'Sake brewing', 'Founded in Horeki 3, a long-established sake brewery that has continued for over 270 years in Sakai City. Its flagship brand "Ippitsu Keijo" is known as a representative local sake of Fukui. Using spring water from the Kuzuryu River and carefully selected sake rice, it carries traditional sake-making into the present.', 'https://www.fukukoma.co.jp/', 'Fukui, Japan', 36.17107, 136.29001, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 192),
    ('Tajima Shuzo', 'Fukui', 'Chubu', '1893', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 26, a long-established sake brewery in Fukui City, Fukui Prefecture. Its flagship brand "Fuku Chitose" is loved as a local sake reflecting Fukui''s character. A skilled brewery carrying on traditional technique while also taking on distinctive sake-making.', 'https://www.fukuchitose.com', 'Fukui, Japan', 36.0609297, 136.2028477, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 63),
    ('Iwao Shoyu Jozomoto', 'Fukui', 'Chubu', '1874', 'food', 'food', 'savory', 'Soy sauce / food manufacturing', 'Founded in Meiji 7, a long-established soy sauce brewery that has continued for over 150 years in Itozaki-cho, Fukui City. Committed to natural fermentation and wooden-barrel aging, it produces soy sauce well suited to sashimi and grilled fish. In recent years it has also offered brewery tours and soy-sauce-making experiences, widely sharing Fukui''s fermentation culture.', 'https://www.iwaoshoyu.net', 'Fukui, Japan', 36.125822, 136.0578841, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.6, 91),
    ('Itajin', 'Fukui', 'Chubu', 'Edo period', 'food', 'food', NULL, 'Ryotei restaurant / inn', 'A long-established ryotei-inn with roughly 400 years of history in Katsuyama City. In a building registered as a tangible cultural property, it serves kaiseki cuisine using seasonal Echizen ingredients as well as traditional "lord''s cuisine." A leading Fukui inn where guests can enjoy a historic setting and local cuisine.', 'https://itajin.com', 'Fukui, Japan', 36.059784, 136.498995, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.8, 177),
    ('Kato Kichibei Shoten', 'Fukui', 'Chubu', '1860', 'food', 'food', NULL, 'Sake brewing', 'Founded in the late Edo period, a long-established sake brewery in Sabae City. Its flagship brand "Born" is a sake brand highly regarded in Japan and abroad. It preserves traditional sake-making while actively expanding into world markets, known as a leading Fukui brewery.', 'https://www.born.co.jp', 'Fukui, Japan', 35.986426, 136.170105, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 122),
    ('Uno Shuzojo', 'Fukui', 'Chubu', '1620', 'food', 'food', NULL, 'Sake brewing', 'Founded in Genna 5, a long-established sake brewery in Ono City. Its flagship brand "Ichinotani" is a fine sake brewed using groundwater from Echizen-Ono, a town famous for its water. With over 400 years of history, it continues community-rooted sake-making.', 'https://www.itinotani.co.jp/', 'Fukui, Japan', 35.986944, 136.488186, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 59),
    ('Sohonke Kitashina Roho', 'Shiga', 'Kansai', '1619', 'food', 'food', 'savory', 'Funazushi (fermented crucian carp sushi) / food manufacturing', 'Founded in Genna 5, one of Shiga Prefecture''s oldest funazushi specialty shops, with over 400 years of history. Using nigorobuna crucian carp from Lake Biwa and Omi rice, it has carried on its traditional wooden-barrel method across 18 generations. A leading shop carrying Shiga''s representative fermented-food culture into the present.', 'https://www.400-kitashina.com/', 'Shiga, Japan', 35.2979668, 136.0120603, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 112),
    ('Honke Rikiken', 'Shiga', 'Kansai', '1810', 'food', 'food', 'sweet', 'Traditional Japanese sweets / teahouse', 'Founded in Bunka 7, a long-established teahouse that has operated on the grounds of Mii-dera Temple for over 200 years. Its specialty "Mii-dera Chikara-mochi" combines soft gyuhi mochi with kinako, matcha, and wasanbon sugar, loved by many worshippers.', 'https://www.tikaraken.com/', 'Shiga, Japan', 35.0110236, 135.8533954, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 70),
    ('Okashitsukasa Umemoto Roho', 'Shiga', 'Kansai', '1885', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 18, a long-established Japanese sweets shop that has continued for over 140 years in Yasu City. Led by its signature "Dorayaki Omi Fuji," it produces seasonal fresh sweets and habutae mochi. A skilled shop with award history at the National Confectionery Exposition.', 'https://umemoto-wagashi.com', 'Shiga, Japan', 35.062504, 136.016763, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 79),
    ('Kakurido', 'Shiga', 'Kansai', '1896', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 29, a long-established Japanese sweets shop in Otsu City. Committed to homemade red bean paste, it carefully handmakes fresh sweets, castella, and dorayaki. A historic shop with a record of confections offered to Emperor Taisho.', 'https://kakurido.com', 'Shiga, Japan', 35.0077101, 135.8623383, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 184),
    ('Itoju Kaho', 'Shiga', 'Kansai', '1809', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Bunka 6, a leading long-established Japanese sweets shop in Hikone City. Its signature confection "Umoregi" is known as a piece associated with the Ii family, lords of Hikone domain, and for over 200 years it has supported the confectionery culture of Hikone''s castle town.', 'https://www.itojyu.com/index.html', 'Shiga, Japan', 35.2711048, 136.2530268, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 81),
    ('Mii-dera Chikaramochi Honke', 'Shiga', 'Kansai', '1869', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 2, a long-loved long-established Japanese sweets shop in Otsu City. Its specialty "Chikaramochi" is characterized by the combination of fragrant kinako and soft mochi, known as a representative confection of Shiga.', 'https://www.tikaramoti.jp/', 'Shiga, Japan', 35.0111151, 135.8629525, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 36),
    ('Okamura Honke', 'Shiga', 'Kansai', '1854', 'food', 'food', NULL, 'Sake brewing', 'Founded in Ansei 1, a long-established sake brewery that has continued for over 170 years in Toyosato Town. Its flagship brand "Kinkame" is a fine Shiga sake brewed using Omi rice and spring water from the Suzuka mountains. Tours of its historic brewery are also popular.', 'https://kin-kame.co.jp/', 'Shiga, Japan', 35.1860804, 136.2322005, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 157),
    ('Fujii Honke', 'Shiga', 'Kansai', '1831', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenpo 2, a long-established sake brewery in Aisho Town. Its flagship brand "Asahi" is also known for its traditional yamahai brewing method, earning high praise from sake enthusiasts nationwide for its flavor reflecting Omi''s local character.', 'https://www.fujiihonke.jp', 'Shiga, Japan', 35.184194, 136.207867, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 92),
    ('Kitajima Shuzo', 'Shiga', 'Kansai', '1805', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunka 2, a long-established sake brewery that has continued for over 220 years in Konan City. Its flagship brand "Miyosakae" is loved as a local Omi sake brewed using local sake rice and famous water from the Suzuka mountains.', 'https://www.kitajima-shuzo.jp/', 'Shiga, Japan', 34.9975, 136.0811111, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 142),
    ('Kita Shuzo', 'Shiga', 'Kansai', '1820', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunsei 3, a long-established sake brewery that has continued for over 200 years in Higashiomi City. Its flagship brand "Kirakucho" is highly regarded as a food-pairing sake, using Omi rice and spring water from the Suzuka mountains. It preserves tradition while continuing sake-making suited to modern food culture.', 'https://kirakucho.com/', 'Shiga, Japan', 35.0843926, 136.2635184, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 67),
    ('Naminooto Shuzo', 'Shiga', 'Kansai', '1805', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunka 2, a long-established sake brewery that has continued for over 220 years in Katata, Otsu City. Its flagship brand "Naminooto," brewed with spring water by the shore of Lake Biwa, is characterized by delicate aroma and soft savoriness. Known as a skilled brewery preserving careful small-batch brewing.', 'https://naminooto.com/', 'Shiga, Japan', 35.1097926, 135.9182244, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 88),
    ('Mifuku Shuzo', 'Shiga', 'Kansai', '1917', 'food', 'food', NULL, 'Sake brewing', 'Founded in Taisho 6, a long-established sake brewery that has continued for over 100 years in Koka City. Its flagship brand "Mifuku" is also known for yamahai brewing and long-aged sake. It carries on traditional technique while actively taking on new sake-making.', 'https://mifuku.co.jp/', 'Shiga, Japan', 34.9742416, 136.1593349, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 106),
    ('Matsuse Shuzo', 'Shiga', 'Kansai', '1860', 'food', 'food', NULL, 'Sake brewing', 'Founded in Man''en 1, a long-established sake brewery in Ryuo Town. Its flagship brand "Matsu no Tsukasa" is a renowned Omi sake highly regarded by sake enthusiasts nationwide. It also grows its own rice, continuing sake-making that draws on the character of its land.', 'https://matsunotsukasa.com', 'Shiga, Japan', 35.083303, 136.118952, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 113),
    ('Emishiki Shuzo', 'Shiga', 'Kansai', '1892', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 25, a long-established sake brewery in Minakuchi, Koka City. Its flagship brand "Emishiki" has drawn attention for innovative sake-making that draws out the character of its yeast. A popular brewery with over 130 years of history, continuing new challenges.', 'https://www.emishiki.com', 'Shiga, Japan', 34.967875, 136.177455, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 145),
    ('Takeuchi Shuzo', 'Shiga', 'Kansai', '1804', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunka 1, a long-established sake brewery in Konan City. Its flagship brand "Kanoizumi" is a local Omi sake long loved locally. Preserving over 220 years of tradition, it continues community-rooted sake-making.', 'https://takeuchishuzo.co.jp/', 'Shiga, Japan', 35.0086792, 136.0574117, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 154),
    ('Ganso Sakamotoya', 'Shiga', 'Kansai', '1869', 'food', 'food', 'savory', 'Funazushi / lake-fish preserves', 'Founded in Meiji 2, a long-established funazushi specialty shop in Otsu City. With a history of being a noren-wake branch of a ryotei serving the Zeze domain, it has carried on its original recipe through single-heir transmission. Beyond funazushi, its simmered lake-fish preserves are also popular, carrying Shiga''s local food culture into the present.', 'https://sakamotoya.biz', 'Shiga, Japan', 35.0080912, 135.8610396, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 165),
    ('Senkien', 'Shiga', 'Kansai', '1661', 'food', 'food', 'sweet', 'Tea / Japanese sweets', 'Founded in the Edo period, a long-established tea shop that has continued for over 150 years in front of Ishiyama-dera Temple. Its matcha sweets and Japanese confections using Omi and Uji tea are popular, long loved by visitors to Ishiyama-dera. Its appeal lies in products blending tradition with modern sensibility.', 'https://www.senkien.jp', 'Shiga, Japan', 35.0288417, 135.9468217, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 143),
    ('Tomita Shuzo', 'Shiga', 'Kansai', '1534', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenbun 3, one of Shiga Prefecture''s oldest sake breweries with over 490 years of history in Kinomoto, Nagahama City. Its flagship brand "Shichihonyari" is known as a fine sake associated with Sengoku-era warlords, highly regarded nationwide for its bold flavor reflecting the character of northern Lake Biwa (Kohoku).', 'https://7yari.co.jp/', 'Shiga, Japan', 35.5050385, 136.2255364, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 35),
    ('Uehara Shuzo', 'Shiga', 'Kansai', '1862', 'food', 'food', NULL, 'Sake brewing', 'Founded in Bunkyu 2, a long-established sake brewery in Takashima City. Its flagship brand "Furosen" is known for yamahai and kimoto brewing methods, preserving sake-making that values natural fermentation. Its distinctive local sake, drawing on the rich nature of Lake Biwa''s western shore, is popular.', 'https://furosen.com/', 'Shiga, Japan', 35.3359937, 136.0554409, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 52),
    ('Okaki Honten', 'Shiga', 'Kansai', '1839', 'food', 'food', 'savory', 'Omi beef specialty shop', 'Founded in Tenpo 10, an Omi beef specialty shop that has continued for over 180 years in Ryuo Town. It sells and serves Omi beef raised on its own ranch, offering the authentic taste through sukiyaki, steak, and shabu-shabu. Nationally known as a leading shop representing Omi beef culture.', 'https://www.okakihonten.jp/', 'Shiga, Japan', 35.046287, 136.1424387, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop&q=80', 4.8, 97),
    ('Omi Beef Moritoshima', 'Shiga', 'Kansai', '1879', 'food', 'food', 'savory', 'Omi beef cuisine', 'Founded in Meiji 12, a leading long-established Omi beef restaurant in Omihachiman City. Its sukiyaki, shabu-shabu, and steak using Omi beef raised on its own ranch are popular and have been loved by many celebrities. A leading shop of Omi beef culture spanning over 140 years.', 'https://oumi-usi.shop/', 'Shiga, Japan', 35.0974194, 136.1013668, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop&q=80', 4.9, 82),
    ('Daiyo', 'Shiga', 'Kansai', '1914', 'shop', 'shop', NULL, 'Japanese candles / food-related tools', 'Founded in Taisho 3, a long-established Japanese-candle shop that has continued for over 110 years in Takashima City. Though not a food shop, its Japanese candles, made using only plant-based materials, are also used at ryotei restaurants and in tea ceremonies. It preserves traditional technique while sharing Shiga''s culture at home and abroad.', 'https://warousokudaiyo.com/', 'Shiga, Japan', 35.400696, 136.030395, 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=800&auto=format&fit=crop&q=80', 4.7, 152),
    ('Akafuku', 'Mie', 'Kansai', '1707', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Hoei 4, a leading long-established Japanese sweets shop in Japan that has continued for over 300 years in front of Ise Grand Shrine''s Naiku. Its specialty "Akafuku Mochi" is characterized by beautiful red bean paste representing the Isuzu River, handed down alongside Ise pilgrimage tradition. Seasonal items such as tsuitachi-mochi and Akafuku Kori (shaved ice) are also popular.', 'https://www.akafuku.co.jp', 'Mie, Japan', 34.4626629, 136.7235667, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 165),
    ('Henbaya Shoten', 'Mie', 'Kansai', '1775', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in An''ei 4, a long-established Japanese sweets shop in Ise City. Its Ise specialty "Henba Mochi" has a simple flavor of fragrantly grilled mochi wrapped around refined smooth red bean paste, preserving a method unchanged for roughly 250 years. Loved as a representative confection of the Ise region.', 'https://henbaya.jp', 'Mie, Japan', 34.5175021, 136.6673134, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 78),
    ('Toraya Uiro', 'Mie', 'Kansai', '1923', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 12, a leading long-established Japanese sweets shop in Ise City. Its chewy Ise uirou is characterized by a distinctive method using wheat flour. It preserves traditional flavor while also offering seasonal limited items, loved by many tourists.', 'https://www.torayauiro.co.jp', 'Mie, Japan', 34.493425, 136.7075786, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 46),
    ('Iwatoya', 'Mie', 'Kansai', '1910', 'food', 'food', 'sweet', 'Traditional Japanese sweets / food', 'Founded in Meiji 43, a long-established shop in front of Ise Grand Shrine''s Naiku. Led by its signature "Iwato Mochi," it handles a wide range including ginger candy and Ise souvenirs. A leading Ise shop that has welcomed worshippers for over 110 years.', 'https://www.iwatoya.co.jp', 'Mie, Japan', 34.4599608, 136.7230706, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 40),
    ('Shunsendo Roho', 'Mie', 'Kansai', '1902', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 35, a long-established Japanese sweets shop in front of Tsubaki Grand Shrine in Suzuka City. Its specialty "Tsubaki Kusa Mochi," fragrant with mugwort, has long been popular with worshippers. It preserves traditional methods while carefully continuing seasonal Japanese sweets.', 'https://syunsendou.com', 'Mie, Japan', 34.960006, 136.4580183, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 73),
    ('Butasute', 'Mie', 'Kansai', '1909', 'food', 'food', 'savory', 'Matsusaka beef specialty shop / eatery', 'Founded in Meiji 42, a long-established butcher shop in Ise City. It handles Matsusaka beef and Kuroge Wagyu, with its beef bowl and croquettes also popular. As a leading food shop around Ise Grand Shrine, it has preserved an unchanging flavor for over 100 years.', 'https://www.butasute.co.jp', 'Mie, Japan', 34.4963872, 136.7018677, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop&q=80', 4.6, 99),
    ('Senokuniya', 'Mie', 'Kansai', '1912', 'food', 'food', 'sweet', 'Food / traditional Japanese sweets', 'Founded in Taisho 1, a long-established shop operating in front of Uji Bridge at Ise Grand Shrine. It offers a range of Ise specialties and souvenirs including its signature "Kamiyo Mochi," long loved as a gateway for Ise pilgrims. It continues to share Ise''s culture while valuing tradition.', 'https://www.senokuniya.co.jp/', 'Mie, Japan', 34.4597464, 136.7219186, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 176),
    ('Miyazaki Honten', 'Mie', 'Kansai', '1846', 'food', 'food', NULL, 'Sake brewing', 'Founded in Koka 3, a long-established sake brewery in Yokkaichi City. Its flagship brand "Miya no Yuki" is a nationally known local sake, and it also produces shochu and liqueurs. A prestigious brewery that has supported Mie''s sake culture for over 170 years.', 'https://www.miyanoyuki.co.jp', 'Mie, Japan', 34.9100043, 136.6336174, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 159),
    ('Shimizu Seizaburo Shoten', 'Mie', 'Kansai', '1869', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 2, a long-established sake brewery that has continued for over 150 years in Suzuka City. Its flagship brand "Zaku" has won numerous awards at home and abroad, highly regarded by sake fans. Its appeal lies in sake-making blending tradition with innovation.', 'https://seizaburo.jp', 'Mie, Japan', 34.868303, 136.622748, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 162),
    ('Nagamochi Sasaiya', 'Mie', 'Kansai', '1550', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in the Sengoku period, a long-established Japanese sweets shop that has continued for over 470 years in Yokkaichi City. Born at the junction of the Tokaido and the Ise pilgrimage road, its "Nagamochi" is loved as a representative Mie confection for its simple flavor of fragrantly grilled mochi and coarse red bean paste.', 'https://www.nagamochi.co.jp', 'Mie, Japan', 34.9719599, 136.6261291, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 71),
    ('Kobaiya', 'Mie', 'Kansai', '1712', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Shotoku 2 (1712), a long-established Japanese sweets shop that has continued for over 250 years in Tsu City. Craftsmen carefully continue making signature confections such as "Miyakodori," yokan, and monaka. Deeply connected to tea-ceremony culture, it has long been loved as a leading Tsu confectioner.', 'https://www.koubaiya.com/', 'Mie, Japan', 34.7664141, 136.1323912, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 93),
    ('Tatsumido', 'Mie', 'Kansai', '1912', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Taisho 1, a long-established Japanese sweets shop in Matsusaka City. Its signature confections "Tsuru no Tama" and "Suzu Monaka" have long been loved locally. Committed to ingredient selection and handcraft, it has supported Matsusaka''s Japanese sweets culture for over 110 years.', 'https://tatsumido.jp', 'Mie, Japan', 34.578064, 136.5301845, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 181),
    ('Kankobai Shuzo', 'Mie', 'Kansai', '1854', 'food', 'food', NULL, 'Sake brewing', 'Founded in Ansei 1, a long-established sake brewery that has continued for over 170 years in Tsu City. Its flagship brand "Kankobai" is nationally popular for its gorgeous aroma and refined flavor. It continues high-quality sake-making while valuing traditional technique.', 'https://www.kankoubai.jp/', 'Mie, Japan', 34.7601308, 136.5227399, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 128),
    ('Ota Shuzo', 'Mie', 'Kansai', '1892', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 25, a long-established sake brewery in Iga City. Its flagship brand "Hanzo" is known for having been served at the Ise-Shima Summit. It has preserved sake-making using Iga basin rice and famous water for over 130 years.', 'https://www.hanzo-sake.com/', 'Mie, Japan', 34.7287774, 136.1226539, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 65),
    ('Takijiman Shuzo', 'Mie', 'Kansai', '1868', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 1, a long-established sake brewery that has continued for over 150 years in Nabari City. Its flagship brand "Takijiman" is highly regarded at the National New Sake Awards. Characterized by sake-making using spring water from the Akame Forty-Eight Falls.', 'https://www.takijiman.jp/', 'Mie, Japan', 34.5963505, 136.0771135, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 142),
    ('Wakaebisu Shuzo', 'Mie', 'Kansai', '1853', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kaei 6, a long-established sake brewery in Iga City. Its flagship brand "Wakaebisu" is characterized by a gentle flavor using Iga rice and pure water. It has continued community-rooted sake-making for over 170 years.', 'https://www.wakaebis.co.jp/', 'Mie, Japan', 34.6686262, 136.180077, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 37),
    ('Nikenjaya Mochi Kadoya Honten', 'Mie', 'Kansai', '1575', 'food', 'food', 'sweet', 'Traditional Japanese sweets / food', 'Founded in Tensho 3, a long-established shop that has continued for over 450 years in Ise City. While carrying its signature "Nikenjaya Mochi" across generations, it is now also nationally known for its "Ise Kadoya Beer" craft beer brand. A leading Ise shop blending tradition with innovation.', 'https://nikenjayamochi.jp/', 'Mie, Japan', 34.4962475, 136.727338, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 169),
    ('Ise Kadoya Beer', 'Mie', 'Kansai', '1575 (main family founding)', 'food', 'food', NULL, 'Food / craft beer', 'A brand carrying on the history of its main family shop, Nikenjaya Mochi Kadoya Honten. While earning worldwide acclaim for its craft beer, it values the spirit of a long-established shop with over 450 years of history.', 'https://www.biyagura.jp', 'Mie, Japan', 34.4611294, 136.7235584, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.8, 93),
    ('Maruhiko Shuzo', 'Mie', 'Kansai', '1918', 'food', 'food', NULL, 'Sake brewing', 'Founded in Taisho 7, a long-established sake brewery that has continued for over 150 years in Yokkaichi City. Its flagship brand "Mie no Kanbai" is known for its refined flavor using spring water from the Suzuka mountains. It continues careful small-batch sake-making.', 'https://www.maruhiko.co.jp', 'Mie, Japan', 34.9706092, 136.5699459, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 72),
    ('Ito Shuzo', 'Mie', 'Kansai', '1847', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kaei 1, a long-established sake brewery in Yokkaichi City. Its flagship brand "Uzume" is loved as a local sake bearing a name associated with Ise Grand Shrine. It continues to preserve traditional technique passed down for over 170 years.', 'https://www.suzukasanroku.com/index.html', 'Mie, Japan', 34.9938947, 136.5385245, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 108),
    ('Hayakawa Shuzobu', 'Mie', 'Kansai', '1873', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 6, a long-established sake brewery that has continued for over 100 years in Kawagoe Town. Its flagship brand "Tenichi" is popular for its gentle flavor using local sake rice. Committed to the handcrafting unique to a small brewery.', 'https://ten-iti.com/', 'Mie, Japan', 35.0165715, 136.6756206, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 57),
    ('Igagoe', 'Mie', 'Kansai', '1873', 'food', 'food', 'savory', 'Soy sauce / miso / seasonings', 'Founded in Meiji 6, a leading long-established food maker in Iga City. It produces a wide range of products including naturally fermented soy sauce, miso, and sauces, supporting Iga''s fermentation culture for over 150 years.', 'https://igagoe.jp/', 'Mie, Japan', 34.761835, 136.132041, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 113),
    ('Gyugin Honten', 'Mie', 'Kansai', '1902', 'food', 'food', 'savory', 'Matsusaka beef cuisine', 'Founded in Meiji 35, a leading long-established restaurant in Matsusaka City. It serves Matsusaka beef sukiyaki and ami-yaki (grilled beef) in the traditional Kansai style, loved by many celebrities. A symbolic shop of Matsusaka beef culture spanning over 120 years.', 'https://www.gyugin-honten.co.jp', 'Mie, Japan', 34.5792122, 136.5284729, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop&q=80', 4.9, 46),
    ('Hyotei', 'Kyoto', 'Kansai', '1576', 'food', 'food', 'savory', 'Kyoto cuisine / ryotei', 'Founded in Tensho 4, a leading long-established ryotei in Kyoto that has continued for over 450 years in front of Nanzenji Temple. Led by its signature "Hyotei Tamago" egg dish, it captivates gourmets in Japan and abroad with Kyoto cuisine based on tea-ceremony kaiseki. Also known as a Michelin three-star establishment.', 'https://hyotei.co.jp', 'Kyoto, Japan', 35.0114133, 135.7867623, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 142),
    ('Minokichi', 'Kyoto', 'Kansai', '1716', 'food', 'food', 'savory', 'Kyoto cuisine / ryotei', 'Founded in Kyoho 1, a distinguished house of Kyoto cuisine with over 300 years of history. Carrying on traditional Kyoto kaiseki that developed from river-fish cuisine, it serves dishes that showcase seasonal ingredients. It has expanded nationwide while preserving Kyoto''s flavor.', 'https://www.minokichi.co.jp', 'Kyoto, Japan', 35.0100529, 135.7851677, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 44),
    ('Hanbey Fu', 'Kyoto', 'Kansai', '1689', 'food', 'food', NULL, 'Fu (wheat gluten) / food manufacturing', 'Founded in Genroku 2, a long-established Kyoto fu shop that has continued for over 330 years. It produces nama-fu and yaki-fu, ingredients essential to Kyoto cuisine. It preserves techniques handed down since its founding while also sharing Kyoto''s food culture through a tea room and museum.', 'https://www.hanbey.co.jp', 'Kyoto, Japan', 34.9953216, 135.7686876, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 192),
    ('Toyouke-ya Yamamoto', 'Kyoto', 'Kansai', '1897', 'food', 'food', 'savory', 'Tofu / food', 'Founded in Meiji 30, a long-established tofu shop that has continued for over 120 years in front of Kitano Tenmangu Shrine. It offers tofu, yuba, and soy milk dishes made with domestic soybeans and famous water, carefully preserving its simple, Kyoto-style flavor.', 'http://www.toyoukeya.co.jp/', 'Kyoto, Japan', 35.02659, 135.739148, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.7, 108),
    ('Murakamiju Honten', 'Kyoto', 'Kansai', '1832', 'food', 'food', 'savory', 'Kyoto pickles', 'Founded in Tenpo 3, a long-established Kyoto pickle shop that has continued for over 170 years. It continues making representative Kyoto pickles such as senmaizuke, shibazuke, and suguki by old-fashioned methods. A leading shop supporting Kyoto''s tables and gift-giving culture.', 'https://www.murakamijyuhonten.co.jp/', 'Kyoto, Japan', 35.0030572, 135.7700924, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.7, 56),
    ('Sasaki Shuzo', 'Kyoto', 'Kansai', '1893', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 26, a long-established brewery known as the only sake brewery within Kyoto''s old city center. Its flagship brand "Jurakudai" is popular for its refined flavor using Kyoto-grown rice and famous water. It has continued sake-making in the heart of Kyoto for over 130 years.', 'https://www.jurakudai.com', 'Kyoto, Japan', 35.0186166, 135.7477539, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 49),
    ('Saito Shuzo', 'Kyoto', 'Kansai', '1895', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 28, a long-established sake brewery in Fushimi. Its flagship brand "Eikun" is highly regarded at the National New Sake Awards. It preserves careful sake-making drawing on Fushimi''s famous water.', 'https://www.eikun.com', 'Kyoto, Japan', 34.9326093, 135.7525631, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 136),
    ('Kitagawa Honke', 'Kyoto', 'Kansai', '1657', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meireki 3, a distinguished Fushimi brewery with over 360 years of history. Its flagship brand "Tomio" is loved at home and abroad as a representative local sake of Kyoto. It continues sake-making that blends tradition with innovation.', 'https://www.tomio-sake.co.jp/', 'Kyoto, Japan', 34.9324483, 135.7566943, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 129),
    ('Sawai Shoyu Honten', 'Kyoto', 'Kansai', '1879', 'food', 'food', 'savory', 'Soy sauce', 'Founded in Meiji 12, a long-established soy sauce shop near the Kyoto Imperial Palace. It preserves natural fermentation using cedar barrels, producing mellow soy sauce suited to Kyoto cuisine. A leading shop carrying its fermentation culture, passed down for over 140 years, into the present.', 'https://sawai-shoyu.shop-pro.jp/', 'Kyoto, Japan', 35.0232588, 135.7564644, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 53),
    ('Honke Nishio Yatsuhashi', 'Kyoto', 'Kansai', '1689', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Genroku 2, a leading shop for Kyoto''s famous yatsuhashi confection. Alongside baked and raw yatsuhashi, it carries on its traditional flavor while also developing new products. It is loved at home and abroad as a representative Kyoto souvenir.', 'https://www.8284.co.jp', 'Kyoto, Japan', 35.0186719, 135.7789639, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 50),
    ('Kameya Yoshinaga', 'Kyoto', 'Kansai', '1803', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kyowa 3, a long-established Kyoto confectioner that has continued for over 220 years. Its signature confection "Karasu-tama" is known as a black red-bean-paste sweet made with bamboo charcoal. It preserves traditional technique while also actively incorporating modern sensibility into its Japanese sweets.', 'https://kameya-yoshinaga.com', 'Kyoto, Japan', 35.0038342, 135.7529822, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 174),
    ('Gekkeikan', 'Kyoto', 'Kansai', '1637', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kanei 14, a leading Fushimi brewery. One of the world''s foremost long-established sake companies, having continued sake-making for over 380 years; its flagship brand "Gekkeikan" is loved worldwide. Its sake museum is also a popular spot.', 'https://www.gekkeikan.co.jp', 'Kyoto, Japan', 34.929136, 135.76161, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 149),
    ('Matsui Shuzo', 'Kyoto', 'Kansai', '1726', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kyoho 11, one of the oldest sake breweries still standing within Kyoto City. Its flagship brand "Kagura" is popular for its refined flavor using Kyoto''s famous water. Having once paused operations, it revived and now continues new sake-making while carrying on its tradition.', 'https://matsuishuzo.com', 'Kyoto, Japan', 35.025425, 135.7735, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 64),
    ('Tamanohikari Shuzo', 'Kyoto', 'Kansai', '1673', 'food', 'food', NULL, 'Sake brewing', 'Founded in Enpo 1, a long-established sake brewery that has continued for over 350 years in Fushimi. Known as a pioneer of the junmai sake revival, it remains committed to sake made entirely from rice. Highly regarded at home and abroad as a distinguished Fushimi, Kyoto brewery.', 'https://www.tamanohikari.co', 'Kyoto, Japan', 34.9379381, 135.7577804, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 85),
    ('Tsuruya Yoshinobu', 'Kyoto', 'Kansai', '1803', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kyowa 3, a distinguished house of Kyoto confectionery that has continued for over 220 years in Nishijin. Its signature confection "Yumochi" and seasonal fresh sweets are highly regarded by various schools of tea ceremony. A long-established shop carrying on beautiful Japanese sweets that reflect Kyoto''s four seasons.', 'https://www.tsuruyayoshinobu.jp', 'Kyoto, Japan', 35.0298519, 135.751447, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 51),
    ('Kanshundo', 'Kyoto', 'Kansai', '1865', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Keio 1, a long-established Kyoto confectioner with over 160 years of history. Alongside tea-ceremony confections and fresh sweets, its craftsman-led Japanese-sweets-making experience is also popular. Loved at home and abroad as a shop where visitors can experience Kyoto''s traditional culture.', 'https://www.kanshundo.co.jp', 'Kyoto, Japan', 34.9917716, 135.7679406, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 112),
    ('Kyo-azuki', 'Kyoto', 'Kansai', '1840', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in the Koka era, a long-established Japanese sweets shop with over 180 years of history. Rooted in a grain wholesaler, it carries on a commitment to selecting azuki beans. Its signature "Mikasa" (dorayaki) and other Kyoto confections, which highlight the ingredients'' natural flavor, are popular.', 'https://www.kyoazuki.jp', 'Kyoto, Japan', 35.0433259, 135.7706982, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.7, 120),
    ('Sasaya Iori', 'Kyoto', 'Kansai', '1716', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Kyoho 1, a distinguished house of Kyoto confectionery with over 300 years of history as a purveyor to the Kyoto Imperial Palace and various temples and shrines. Its signature confection "Dorayaki" is known for being sold only on the 20th–22nd of each month. It preserves tradition while also developing new Kyoto confections.', 'https://www.sasayaiori.com', 'Kyoto, Japan', 34.9890051, 135.7485963, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 87),
    ('Kameya Kiyonaga', 'Kyoto', 'Kansai', '1617', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Genna 3, a long-established Japanese sweets shop that has continued for over 400 years in front of Yasaka Shrine. Its signature confection "Seijo Kangiden" is a piece carrying one of Japan''s oldest tang-style confections into the present. A leading Kyoto shop deeply connected to tea-ceremony culture.', 'https://www.kameyakiyonaga.co.jp', 'Kyoto, Japan', 35.0030326, 135.7769366, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 167),
    ('Mamemasa', 'Kyoto', 'Kansai', '1884', 'food', 'food', 'sweet', 'Bean confections / food manufacturing', 'Founded in Meiji 17, a Kyoto bean-confection specialty shop with over 140 years of history. Its five-color beans and Ebisugawa five-color beans are nationally known as Kyoto souvenirs. It preserves old-fashioned methods while actively taking on new bean-confection making.', 'https://www.mamemasa.co.jp', 'Kyoto, Japan', 35.0148627, 135.7636526, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.6, 163),
    ('Mametomi Honpo', 'Kyoto', 'Kansai', '1908', 'food', 'food', 'sweet', 'Bean confections / food manufacturing', 'Founded in Meiji 41, a long-established maker that has focused solely on bean confections for over 100 years. It offers a wide range from roasted beans and setsubun beans to gift bean confections, continuing product-making committed to ingredient selection and quality control.', 'https://mametomi.jp', 'Kyoto, Japan', 34.9896394, 135.7542842, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 74),
    ('Yamanaka Aburaten', 'Kyoto', 'Kansai', '1800', 'food', 'food', 'savory', 'Cooking oil / food', 'Founded in the Edo period, a long-established Kyoto oil specialty shop with over 200 years of history. It handles carefully selected cooking oils from sesame and rapeseed oil to olive oil, trusted by many chefs. Known as a leading shop supporting Kyoto cuisine.', 'https://www.yoil.co.jp', 'Kyoto, Japan', 35.0202421, 135.7458375, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.8, 81),
    ('Kawakatsu Sohonke', 'Kyoto', 'Kansai', '1917', 'food', 'food', 'savory', 'Kyoto pickles', 'Founded in Taisho 6, a long-established Kyoto pickle shop with over 100 years of history. It produces representative Kyoto pickles such as senmaizuke, shibazuke, and narazuke, preserving tradition while also working on new product development.', 'https://www.kawakatsu.com', 'Kyoto, Japan', 34.9980412, 135.7490746, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.6, 103),
    ('Hara Ryokaku', 'Kyoto', 'Kansai', '1685', 'food', 'food', 'savory', 'Spices / food manufacturing', 'Founded in Jokyo 2, a long-established Kyoto spice shop with over 320 years of history. Its specialty "Kuro Shichimi" (black seven-spice blend) is known as a piece favored by restaurants in Gion. It supports Kyoto''s food culture with blending techniques passed down through generations.', 'https://hararyoukaku.co.jp', 'Kyoto, Japan', 35.0039542, 135.7749408, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=800&auto=format&fit=crop&q=80', 4.9, 110),
    ('Masuda Tokubei Shoten', 'Kyoto', 'Kansai', '1675', 'food', 'food', NULL, 'Sake brewing', 'Founded in Enpo 3, a long-established Fushimi brewery with over 350 years of history. Its flagship brand "Tsuki no Katsura" is also known as the brand that created Japan''s first sparkling sake. One of Kyoto''s leading breweries balancing tradition and innovation.', 'https://tsukinokatsura.co.jp/', 'Kyoto, Japan', 34.9402189, 135.7427152, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 96),
    ('Shotoku Shuzo', 'Kyoto', 'Kansai', '1645', 'food', 'food', NULL, 'Sake brewing', 'Founded in Shoho 2, a long-established Fushimi brewery with over 380 years of history. Centered on junmai sake, it continues sake-making using Kyoto-grown rice, known for brands such as "Karaku." It preserves tradition while also pursuing quality improvement.', 'https://www.shoutoku.co.jp', 'Kyoto, Japan', 34.9405999, 135.7566521, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 58),
    ('Kinshi Masamune', 'Kyoto', 'Kansai', '1781', 'food', 'food', NULL, 'Sake brewing', 'Founded in Tenmei 1, a long-established Kyoto brewery with over 240 years of history. Its flagship brand "Kinshi Masamune" is known as sake using Kyoto''s famous "Momo no I" water. With a brewery museum on site, it continues to spread Kyoto''s sake culture.', 'http://kinshimasamune.com/', 'Kyoto, Japan', 34.9403359, 135.7621214, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 183),
    ('Tsuen', 'Kyoto', 'Kansai', '1160', 'food', 'food', NULL, 'Tea / teahouse', 'Founded in Eiryaku 1, one of Japan''s oldest tea shops, with over 860 years of history at the western end of Uji Bridge. Known as a symbol of Uji tea culture, it serves matcha and sencha in a historic building. A leading shop carrying tradition passed down through generations and Uji''s atmosphere into the present.', 'https://tsuentea.com/', 'Kyoto, Japan', 34.89329, 135.8072759, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.7, 112),
    ('Fukujuen Kyoto Main Store', 'Kyoto', 'Kansai', '1790', 'food', 'food', NULL, 'Tea / food', 'Founded in Kansei 2, a leading Kyoto tea shop with over 230 years of history. It preserves the tradition of Uji tea while spreading the appeal of Japanese tea at home and abroad. With a tea salon and experience facility on site, it broadly conveys Kyoto''s tea culture.', 'https://www.fukujuen.com', 'Kyoto, Japan', 35.0035269, 135.7648322, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80', 4.9, 182),
    ('Tsujiri Ichihonten', 'Kyoto', 'Kansai', '1860', 'food', 'food', 'sweet', 'Tea / traditional Japanese sweets', 'Founded in Man''en 1, a long-established tea shop that spread Uji matcha nationwide. It sells high-quality matcha, gyokuro, and matcha confections, deeply connected to tea ceremony and Kyoto''s tea culture. A distinguished house of Uji tea with over 160 years of history.', 'https://www.tsujiri.co.jp', 'Kyoto, Japan', 34.8903372, 135.8027016, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 182),
    ('Nakamura Tokichi Honten', 'Kyoto', 'Kansai', '1854', 'food', 'food', 'sweet', 'Tea / sweets', 'Founded in Ansei 1, a leading long-established tea shop in Uji City. Its Uji tea, matcha sweets, and tea soba are popular, and its historic shop has become a tourist attraction. It has continued spreading the appeal of Uji tea for over 170 years.', 'https://www.tokichi.jp', 'Kyoto, Japan', 34.8895072, 135.8017988, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 82),
    ('Honda Miso Honten', 'Kyoto', 'Kansai', '1830', 'food', 'food', 'savory', 'Miso / food manufacturing', 'Founded in Tenpo 1, a long-established miso shop that has continued for over 190 years west of the Kyoto Imperial Palace. Led by Saikyo white miso, it produces miso essential to Kyoto cuisine, trusted by many ryotei restaurants and chefs.', 'https://www.honda-miso.co.jp', 'Kyoto, Japan', 35.0263617, 135.7578455, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.6, 91),
    ('Inoue Tsukemono-ten', 'Kyoto', 'Kansai', '1872', 'food', 'food', 'savory', 'Kyoto pickles', 'Founded in Meiji 5, a long-established Kyoto pickle shop with over 150 years of history. It carefully produces traditional Kyoto pickles such as suguki and senmaizuke, long loved by local customers and tourists alike.', 'https://inoue-tsukemono.com/', 'Kyoto, Japan', 34.998982, 135.753834, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.9, 110),
    ('Iseya Honten', 'Hyogo', 'Kansai', '1753', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Horeki 3, a long-established Japanese sweets shop that has continued for over 270 years in Himeji''s castle town. Its signature confection "Tamatsubaki" is known as a sweet associated with the Himeji domain, long loved for its refined white azuki paste and gyuhi. A leading shop representing Himeji.', 'https://www.iseyahonten.com', 'Hyogo, Japan', 34.8324721, 134.689281, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 93),
    ('Mangetsudo', 'Hyogo', 'Kansai', '1877', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 10, a long-established Japanese sweets shop in Kita Ward, Kobe City. Its specialty "Toyosuke Manju" is characterized by a thin skin and refined smooth red bean paste, long loved by travelers on the Arima Kaido road. A Kobe shop preserving a method unchanged for over 140 years.', 'https://www.mangetsudo.jp', 'Hyogo, Japan', 34.8136896, 135.0989859, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.8, 53),
    ('Matsubado', 'Hyogo', 'Kansai', '1868', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Meiji 1, a long-established Japanese sweets shop that has continued for over 150 years in Inami Town. Craftsmen carefully handmake seasonal fresh sweets, daifuku, and dorayaki. A leading Harima shop continuing community-rooted confectionery.', 'https://www.matsubado.jp', 'Hyogo, Japan', 34.7534633, 134.9450946, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 114),
