    ('Kiku-Masamune Shuzo', 'Hyogo', 'Kansai', '1659', 'food', 'food', NULL, 'Sake brewing', 'Founded in Manji 2, a leading long-established brewery representing the Nada-Gogo brewing district. Its flagship brand "Kiku-Masamune" is nationally known as synonymous with dry sake, preserving sake-making passed down for over 360 years. Its sake museum is also popular.', 'https://www.kikumasamune.co.jp', 'Hyogo, Japan', 34.7085614, 135.2679141, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 71),
    ('Hakutsuru Shuzo', 'Hyogo', 'Kansai', '1743', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kanpo 3, a distinguished brewery in the Nada-Gogo district with over 280 years of history. Its flagship brand "Hakutsuru" is widely loved at home and abroad, and its sake museum lets visitors learn about sake culture.', 'https://www.hakutsuru.co.jp', 'Hyogo, Japan', 34.7100728, 135.2616604, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 78),
    ('Sawanotsuru', 'Hyogo', 'Kansai', '1717', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kyoho 2, a long-established brewery in Kobe''s Nada district with over 300 years of history. Known for sake-making using the famous "Miyamizu" water and quality sake rice, it preserves tradition while continuing new challenges.', 'https://www.sawanotsuru.co.jp', 'Hyogo, Japan', 34.7032423, 135.2332237, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 178),
    ('Osawa Honke Shuzo', 'Hyogo', 'Kansai', '1717', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kyoho 2, a long-established sake brewery that has continued for over 300 years in Nishinomiya. Its flagship brand "Tokuwaka" is loved as a local sake carrying on Nada''s tradition. A small but skilled brewery continuing careful sake-making.', 'https://www.osawashuzo.co.jp', 'Hyogo, Japan', 34.725039, 135.342228, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 107),
    ('Ibaraki Shuzo', 'Hyogo', 'Kansai', '1848', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kaei 1, a long-established sake brewery that has continued for over 170 years in Uozumi-cho, Akashi City. Its flagship brand "Rairaku" is popular as a local sake that pairs well with Akashi''s seafood. Its historic brewery is also open for tours.', 'https://www.ibaraki-shuzo.com', 'Hyogo, Japan', 34.6897332, 134.8973413, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 134),
    ('Nadagiku Shuzo', 'Hyogo', 'Kansai', '1910', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 43, a long-established sake brewery that has continued for over 110 years in Himeji City. Its flagship brand "Nadagiku" is loved as a local sake using Himeji''s famous water. A popular spot with a brewery tour and restaurant on site.', 'https://www.nadagiku.co.jp', 'Hyogo, Japan', 34.8165169, 134.6808015, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.9, 194),
    ('Kenbishi Shuzo', 'Hyogo', 'Kansai', '1505', 'food', 'food', NULL, 'Sake brewing', 'Founded in Eisho 2, one of Japan''s oldest sake breweries with over 500 years of history. Its flagship brand "Kenbishi," representing the Nada-Gogo district, is known for its bold savoriness and traditional flavor. It preserves sake-making passed down across the ages.', 'https://www.kenbishi.co.jp', 'Hyogo, Japan', 34.710095, 135.256723, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.8, 149),
    ('Sakura Masamune', 'Hyogo', 'Kansai', '1625', 'food', 'food', NULL, 'Sake brewing', 'Founded in Kanei 2, a distinguished brewery in the Nada-Gogo district with over 400 years of history. Known for being deeply involved in the discovery of Miyamizu water, it has made a major contribution to improving sake quality. Its flagship brand "Sakura Masamune" is loved nationwide.', 'https://www.sakuramasamune.co.jp', 'Hyogo, Japan', 34.7098435, 135.2714369, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 140),
    ('Hamafukutsuru Ginjo Kobo', 'Hyogo', 'Kansai', '1716', 'food', 'food', NULL, 'Sake brewing', 'A Nada brewery carrying on a history dating to its founding in Kyoho 1. It brews brands such as "Sorakura" and is also popular as a facility offering brewery tours and tastings. Its appeal lies in sake-making blending tradition with modern technology.', 'https://www.hamafukutsuru.co.jp', 'Hyogo, Japan', 34.7096452, 135.272953, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.6, 83),
    ('Kamitaka (Eigashima Shuzo)', 'Hyogo', 'Kansai', '1888', 'food', 'food', NULL, 'Sake brewing', 'Founded in Meiji 21, a long-established sake brewery that has continued for over 130 years in Akashi City. Led by its flagship brand "Kamitaka," it brews a wide range including sake, shochu, and whiskey. A distinguished producer drawing on Akashi''s local character.', 'https://www.ei-sake.jp', 'Hyogo, Japan', 34.681342, 134.9054299, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop&q=80', 4.7, 64),
    ('Nippon Maruten Shoyu', 'Hyogo', 'Kansai', '1795', 'food', 'food', 'savory', 'Soy sauce / seasonings', 'Founded in Kansei 7, a long-established soy sauce maker that has continued for over 230 years in Tatsuno City. Carrying on the tradition of light-colored (usukuchi) soy sauce, it offers a range of products including ponzu and dashi soy sauce. A company representing Harima''s fermentation culture.', 'https://www.marten-fi.co.jp', 'Hyogo, Japan', 34.8480651, 134.5377856, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.7, 168),
    ('Suehiro Shoyu', 'Hyogo', 'Kansai', '1879', 'food', 'food', 'savory', 'Soy sauce / food manufacturing', 'Founded in Meiji 12, a long-established soy sauce brewery that has continued for over 140 years in Tatsuno. Committed to natural fermentation using domestic soybeans and wheat, it preserves the tradition of wooden-barrel brewing. A leading shop for the usukuchi soy sauce also loved in Kyoto cuisine.', 'https://www.suehiro-kanei.online', 'Hyogo, Japan', 34.8693478, 134.5482518, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.6, 39),
    ('Ikemoto Shoyu (Kiku Murasaki)', 'Hyogo', 'Kansai', '1885', 'food', 'food', 'savory', 'Soy sauce / food manufacturing', 'Founded in Meiji 18, a long-established soy sauce brewery that has continued for over 140 years in Kobe City. It offers its locally loved "Kiku Murasaki" brand, producing regionally distinctive products such as sashimi soy sauce, ponzu, and soy sauce made specifically for ikanago (sand lance) simmering.', 'https://www.kikumurasaki.co.jp', 'Hyogo, Japan', 34.7174492, 135.0405612, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.8, 169),
    ('Adachi Jozo', 'Hyogo', 'Kansai', '1889', 'food', 'food', 'savory', 'Soy sauce / miso', 'Founded in Meiji 22, a long-established brewer that has continued for over 130 years in Taka Town. It continues natural fermentation in wooden barrels used for over 100 years, also known for its organic JAS-certified soy sauce. A leading Harima shop that carefully preserves traditional methods.', 'https://www.adachi-jozo.co.jp', 'Hyogo, Japan', 35.078758, 134.891457, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800&auto=format&fit=crop&q=80', 4.9, 166),
    ('Amaneya', 'Hyogo', 'Kansai', '1867', 'food', 'food', 'sweet', 'Traditional Japanese sweets', 'Founded in Keio 3, a long-established Japanese sweets shop that has continued for over 150 years in Himeji City. Craftsmen carefully continue making fresh sweets, yokan, and monaka one by one. A popular shop carrying the confectionery culture of Himeji''s castle town into the present.', 'https://www.amaneya.jp', 'Hyogo, Japan', 34.8308731, 134.6438072, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=800&auto=format&fit=crop&q=80', 4.9, 194)
) AS v(shop_name, prefecture, region, founded, category, pin_type, flavor_type, subcategory, description, website, address, lat, lng, image_url, rating, reviews_count)
WHERE NOT EXISTS (
    SELECT 1 FROM public.century_shops existing
    WHERE existing.shop_name = v.shop_name AND existing.prefecture = v.prefecture
);

-- 5. Create indexes for fast filtering by region, prefecture, pin_type, and coordinates
CREATE INDEX IF NOT EXISTS idx_century_shops_region ON public.century_shops(region);
CREATE INDEX IF NOT EXISTS idx_century_shops_prefecture ON public.century_shops(prefecture);
CREATE INDEX IF NOT EXISTS idx_century_shops_pin_type ON public.century_shops(pin_type);
CREATE INDEX IF NOT EXISTS idx_century_shops_lat_lng ON public.century_shops(lat, lng);
